-- Παράχθηκε από tools/moves-sql.js στις 2026-09-15T01:11:38.295Z · 19 κινήσεις
begin;
insert into public.nomosio_moves
  (id, sort, theme, title, who, benefit, law, nomosio_ref, steps, watch_out,
   deadline_text, deadline_url, action_url, sources, checked_on, active, updated_at)
values
  ('yperories-dikaiomata-arnisi-40', 110, 'work', 'Μάθε τα δικαιώματά σου όταν σου ζητούν υπερωρία', array['μισθωτός']::text[], 'Μαθαίνεις τι λέει ο νόμος για την υπερωρία: πόσες ώρες επιτρέπονται, τι προσαύξηση προβλέπεται και πότε μπορείς να αρνηθείς.', 'Ν. 5239/2025', '/tekmiria/nomoi', '["Ο νόμος επιτρέπει πλέον έως 13 ώρες δουλειά τη μέρα και στον ίδιο εργοδότη, όχι μόνο σε δύο διαφορετικούς. Πρέπει όμως να τηρούνται όλα τα όρια για τις ώρες εργασίας και την ανάπαυση (πηγή: Υπουργείο Εργασίας).","Για κάθε ώρα νόμιμης υπερωρίας, έως 4 ώρες τη μέρα και έως 150 ώρες τον χρόνο, ο νόμος προβλέπει ωρομίσθιο αυξημένο κατά 40% (ΦΕΚ Α΄ 178/2025, άρθρο 7). Έλεγξε αν αυτή η προσαύξηση φαίνεται στη μισθοδοσία σου.","Ο νόμος σου δίνει δικαίωμα να αρνηθείς την υπερωρία, αλλά όχι σε κάθε περίπτωση. Κατά τον Κώδικα Εργατικού Δικαίου (άρθρο 12), αν υπάρχει ανάγκη, πρέπει να κάνεις την επιπλέον δουλειά όταν μπορείς και η άρνησή σου θα ήταν αντίθετη με την καλή πίστη. Όταν η άρνηση είναι νόμιμη, δεν επιτρέπεται να σου φέρει απόλυση, χειρότερους όρους ή διακρίσεις (ΦΕΚ Α΄ 178/2025, άρθρα 7 και 16).","Αν δεν σου πληρώνουν τις υπερωρίες ή σε πιέζουν επειδή αρνήθηκες, μπορείς να κάνεις καταγγελία στην Επιθεώρηση Εργασίας. Θα χρειαστείς την επωνυμία και το ΑΦΜ του εργοδότη και τη διεύθυνση του χώρου εργασίας. Κράτα αντίγραφα από μισθοδοσίες και μηνύματα.","Για επώνυμη καταγγελία μέσω gov.gr χρειάζεσαι κωδικούς για τις ηλεκτρονικές υπηρεσίες της Επιθεώρησης Εργασίας. Μπορείς να την κάνεις και χωρίς εγγραφή, ακόμη και ανώνυμα."]'::jsonb, 'Το δικαίωμα άρνησης δεν είναι απόλυτο και ο νόμος δεν λέει με ακρίβεια πότε μια άρνηση είναι αντίθετη με την καλή πίστη. Πριν αρνηθείς, ρώτα την Επιθεώρηση Εργασίας στο 1555, το σωματείο σου ή δικηγόρο. Αν σε απολύσουν, η προθεσμία για να προσβάλεις την απόλυση στο δικαστήριο είναι λίγων μηνών και η καταγγελία στην Επιθεώρηση δεν τη σταματά: μίλησε αμέσως με δικηγόρο.', null, null, 'https://www.gov.gr/upourgeia/oloi-foreis/epitheorese-ergasias/eponume-kataggelia', '[{"title":"Νόμος 5239/2025 «Δίκαιη Εργασία για όλους» - Υπουργείο Εργασίας και Κοινωνικής Ασφάλισης","url":"https://ypergasias.gov.gr/ergani/nomos-5239-2025-dikaii-ergasia-gia-olous/","confirms":"Επέκταση της δυνατότητας εργασίας έως 13 ώρες ημερησίως, που ίσχυε για 2 εργοδότες, και στον ίδιο εργοδότη· υπερωρία με νόμιμη προσαύξηση 40%."},{"title":"ΦΕΚ Α΄ 178/17.10.2025 (Ν. 5239/2025), αρχείο του ΦΕΚ στον ιστότοπο του ΕΛΙΝΥΑΕ","url":"https://www.elinyae.gr/sites/default/files/2025-10/178a_2025_0.pdf","confirms":"Άρθρο 7 (τροποποίηση άρθρου 194 παρ. 2 και 3 Κώδικα Εργατικού Δικαίου): ο εργαζόμενος έχει δικαίωμα να αρνηθεί την υπερωρία «όπως προβλέπεται στο άρθρο 12», η άρνηση δεν συνιστά λόγο καταγγελίας της σύμβασης ούτε οδηγεί σε βλαπτική μεταβολή ή δυσμενή διάκριση· αμοιβή ίση με το ωρομίσθιο προσαυξημένο κατά 40% για κάθε ώρα νόμιμης υπερωρίας, έως 4 ώρες ημερησίως και έως 150 ώρες ετησίως, με την επιφύλαξη των διατάξεων για χρόνο εργασίας και ανάπαυσης. Άρθρο 16: προσθήκη στο άρθρο 350 παρ. 1 περ. γ΄ (υποπερ. γιε΄) της προστασίας από απόλυση για όσους αρνούνται υπερωρία. Κεφαλίδα: Τεύχος Α΄ 178/17.10.2025."},{"title":"Νόμος 5239/2025 (Κωδικοποιημένος) - kodiko.gr","url":"https://www.kodiko.gr/nomothesia/document/1230018/nomos-5239-2025","confirms":"Στοιχεία δημοσίευσης: ΦΕΚ Α 178/17.10.2025."},{"title":"Επώνυμη καταγγελία στην Επιθεώρηση Εργασίας - Gov.gr","url":"https://www.gov.gr/upourgeia/oloi-foreis/epitheorese-ergasias/eponume-kataggelia","confirms":"Καταγγελία κατά επιχείρησης για παραβιάσεις της εργατικής νομοθεσίας· απαιτούνται κωδικοί πρόσβασης στις ηλεκτρονικές υπηρεσίες της Επιθεώρησης Εργασίας, επωνυμία και ΑΦΜ εργοδότη, διεύθυνση τόπου ελέγχου και θέματα προς διερεύνηση. Το περιεχόμενο αποδίδεται με JavaScript· επιβεβαιώθηκε και σε browser."},{"title":"Ανώνυμη Καταγγελία - Επιθεώρηση Εργασίας","url":"https://www.hli.gov.gr/odigies-ilektronikon-ypiresion/ergasiakes-scheseis-ilektronikes-ypiresies/anonymi-katangelia/","confirms":"Για καταγγελία σε βάρος εργοδότη δεν απαιτείται εγγραφή· υποβάλλεται ανώνυμα ή επώνυμα, με υποχρεωτικά ΑΦΜ και επωνυμία εργοδότη και πλήρη διεύθυνση χώρου εργασίας. Σημείωση ελέγχου: το WebFetch απέτυχε με σφάλμα πιστοποιητικού TLS· η σελίδα φόρτωσε κανονικά σε browser και με curl (HTTP 200)."},{"title":"ΦΕΚ Α΄ 121/11.07.2025 — Κώδικας Εργατικού Δικαίου (π.δ. 62/2025)","url":"https://gslegal.gov.gr/wp-content/uploads/2025/07/%CE%91-121.pdf","confirms":"Άρθρο 12: ο εργαζόμενος έχει υποχρέωση να παράσχει εργασία πέρα από τη συμφωνημένη, αν είναι σε θέση και η άρνησή του θα ήταν αντίθετη με την καλή πίστη."}]'::jsonb, '2026-09-14'::date, true, now()),
  ('myergani-elegxos-oron-yperorion', 120, 'work', 'Έλεγξε στο myErgani τις ώρες που δήλωσε ο εργοδότης', array['μισθωτός']::text[], 'Βλέπεις αν το ωράριο και οι υπερωρίες που καταγράφονται για σένα ταιριάζουν με όσες πραγματικά δούλεψες, ώστε να εντοπίσεις νωρίς αν κάτι λείπει.', 'Κώδικας Εργατικού Δικαίου (π.δ. 62/2025), άρθρο 580· Ν. 5239/2025, άρθρο 5', '/tekmiria/nomoi', '["Κατέβασε την εφαρμογή myErgani από το Google Play ή το App Store. Την πρώτη φορά μπαίνεις με τους κωδικούς σου στο Taxisnet.","Άνοιξε την οθόνη «Ημερολόγιο». Εκεί βλέπεις το ωράριο που δήλωσε ο εργοδότης, τις υπερωρίες, τις άδειες και τα στοιχεία πραγματικής εργασίας από την ψηφιακή κάρτα.","Δες και την οθόνη «Δηλώσεις» για ό,τι έχει καταθέσει ο εργοδότης για σένα, όπως το καθεστώς απασχόλησης ή τις άδειές σου.","Σύγκρινε τις ώρες και τις υπερωρίες με όσες πραγματικά δούλεψες και με τη μισθοδοσία σου. Κράτα σημειώσεις για ό,τι δεν ταιριάζει.","Για απορίες πάρε τηλέφωνο στο 1555 του Υπουργείου Εργασίας. Κράτα στιγμιότυπα οθόνης από ό,τι δεν ταιριάζει, γιατί οι δηλώσεις μπορεί να αλλάξουν αργότερα. Αν οι ώρες ή οι υπερωρίες δεν δηλώνονται σωστά, μπορείς να κάνεις καταγγελία στην Επιθεώρηση Εργασίας. Η καταγγελία δεν αντικαθιστά την αγωγή για απλήρωτες αποδοχές."]'::jsonb, 'Η ψηφιακή κάρτα εργασίας δεν καλύπτει ακόμη όλες τις επιχειρήσεις και επεκτείνεται σταδιακά, οπότε αν ο εργοδότης σου δεν έχει ενταχθεί μπορεί να μη βρεις στοιχεία πραγματικής εργασίας.', null, null, 'https://www.gov.gr/ipiresies/epikheirematike-drasterioteta/elektronikos-phakelos-epikheireses/myergani-app-psephiake-karta-ergasias-gia-ergazomenous', '[{"title":"Πως Λειτουργεί: Για Εργαζόμενους - Ψηφιακή Κάρτα Εργασίας","url":"https://psifiakikarta.gov.gr/pos-leitoyrgei-ergazomenoys/","confirms":"Η εφαρμογή myErgani κατεβαίνει από Google Play ή App Store· πρώτη σύνδεση με κωδικούς Taxisnet· οθόνες «Εργοδότες», «Δηλώσεις» (π.χ. καθεστώς απασχόλησης, άδειες), «Ημερολόγιο» (δηλώσεις ωραρίου, υπερωρίες, άδειες και δεδομένα πραγματικής εργασίας από την κάρτα) και «Κάρτα» (QR code)."},{"title":"myErgani app, ψηφιακή κάρτα εργασίας για εργαζόμενους - Gov.gr","url":"https://www.gov.gr/ipiresies/epikheirematike-drasterioteta/elektronikos-phakelos-epikheireses/myergani-app-psephiake-karta-ergasias-gia-ergazomenous","confirms":"Το myErgani δίνει πρόσβαση στα στοιχεία που δηλώνουν οι εργοδότες στην ΕΡΓΑΝΗ, σε όλες τις δηλώσεις τους, στο πρόγραμμα εργασίας (ωράριο, βάρδιες, υπερωρίες, άδειες) και στο ημερολόγιο πραγματικής απασχόλησης· χρειάζονται κωδικοί Taxisnet. Το περιεχόμενο αποδίδεται με JavaScript· επιβεβαιώθηκε και σε browser."},{"title":"Ψηφιακή Κάρτα Εργασίας","url":"https://psifiakikarta.gov.gr/psifiaki-karta-ergasias/","confirms":"Η εφαρμογή του μέτρου επεκτείνεται σταδιακά στο σύνολο των επιχειρήσεων (σήμερα καλύπτει συγκεκριμένους κλάδους)· οι εργαζόμενοι βλέπουν ώρες, ρεπό και άδειες μέσω myErgani app· τηλέφωνο Υπουργείου Εργασίας 1555."},{"title":"Επώνυμη καταγγελία στην Επιθεώρηση Εργασίας - Gov.gr","url":"https://www.gov.gr/upourgeia/oloi-foreis/epitheorese-ergasias/eponume-kataggelia","confirms":"Υπάρχει ηλεκτρονική καταγγελία κατά επιχείρησης για παραβιάσεις της εργατικής νομοθεσίας."},{"title":"ΦΕΚ Α΄ 121/11.07.2025 — Κώδικας Εργατικού Δικαίου (π.δ. 62/2025)","url":"https://gslegal.gov.gr/wp-content/uploads/2025/07/%CE%91-121.pdf","confirms":"Άρθρο 580: ψηφιακή κάρτα εργασίας."}]'::jsonb, '2026-09-14'::date, true, now()),
  ('katotatos-misthos-920-elegxos-misthodosias', 130, 'work', 'Έλεγξε αν ο μισθός σου φτάνει τον κατώτατο', array['μισθωτός']::text[], 'Αν πληρώνεσαι κάτω από τον κατώτατο μισθό, το εντοπίζεις και μπορείς να ζητήσεις έλεγχο από την Επιθεώρηση Εργασίας.', 'Κώδικας Εργατικού Δικαίου (π.δ. 62/2025), άρθρα 141 και 402', '/tekmiria/nomoi', '["Από 1 Απριλίου 2026 ο βασικός κατώτατος μισθός για υπαλλήλους πλήρους απασχόλησης είναι 920 € τον μήνα και το κατώτατο ημερομίσθιο για εργατοτεχνίτες 41,09 € (πηγή: Υπουργείο Εργασίας). Αν έχεις προϋπηρεσία, το ελάχιστο που δικαιούσαι μπορεί να είναι μεγαλύτερο.","Έλεγξε αν δικαιούσαι προσαύξηση για προϋπηρεσία. Μετράει η δουλειά σου ως μισθωτός σε οποιονδήποτε εργοδότη πριν από τις 14.2.2012 και μετά από την 1.1.2024. Ο χρόνος ανάμεσα σε αυτές τις δύο ημερομηνίες δεν μετράει. Οι υπάλληλοι παίρνουν 10% για κάθε τριετία, έως 3 τριετίες. Οι εργατοτεχνίτες παίρνουν 5% για κάθε τριετία, έως 6 τριετίες (Κώδικας Εργατικού Δικαίου, άρθρο 402). Μετά πάρε τη μισθοδοσία σου από τον Απρίλιο 2026 και δες τον μισθό ή το ημερομίσθιο πριν από τις κρατήσεις.","Μην τον συγκρίνεις με ό,τι μπαίνει στον λογαριασμό σου. Το Υπουργείο δίνει ενδεικτικά ποσά: για μισθό 920 € υπολογίζει καθαρά 797 € για εργαζόμενο κάτω των 25 και 781 € για 26 έως 30 ετών. Τα δικά σου καθαρά μπορεί να διαφέρουν.","Αν ο μισθός σου είναι χαμηλότερος, ζήτα εξήγηση από τον εργοδότη ή κάνε καταγγελία στην Επιθεώρηση Εργασίας, επώνυμα μέσω gov.gr ή χωρίς εγγραφή, ακόμη και ανώνυμα."]'::jsonb, 'Τα 920 € είναι το κατώτερο όριο για υπάλληλο πλήρους απασχόλησης χωρίς προσαύξηση προϋπηρεσίας. Συλλογική σύμβαση ή η προϋπηρεσία σου μπορεί να σου δίνουν περισσότερα. Αν δουλεύεις λιγότερες ώρες ή δεν ξέρεις τι ισχύει για σένα, ρώτα την Επιθεώρηση Εργασίας στο 1555. Αν ήδη πληρώνεσαι πάνω από το νόμιμο ελάχιστο, η προσαύξηση μπορεί να καλύπτεται από όσα ήδη παίρνεις.', null, null, 'https://www.gov.gr/upourgeia/oloi-foreis/epitheorese-ergasias/eponume-kataggelia', '[{"title":"Νέα αύξηση κατώτατου μισθού - Υπουργείο Εργασίας και Κοινωνικής Ασφάλισης (26.3.2026)","url":"https://ypergasias.gov.gr/nea-afxisi-katotatou-misthou-ena-akomi-simantiko-vima-gia-ti-dievrynsi-tou-diathesimou-eisodimatos-ergazomenon/","confirms":"Από την 1η Απριλίου 2026: 920 € για υπαλλήλους πλήρους απασχόλησης (από 880 €) και ημερομίσθιο εργατοτεχνιτών 41,09 € (από 39,30 €)· καθαρές μηνιαίες απολαβές 797 € για εργαζόμενο κάτω των 25 και 781 € για 26 έως 30 ετών."},{"title":"Υπ. Απόφαση 8934/2026 - kodiko.gr","url":"https://www.kodiko.gr/nomothesia/document/1306460/yp.-apofasi-8934-2026","confirms":"Η απόφαση 8934/2026 για τον νομοθετημένο κατώτατο μισθό δημοσιεύθηκε στο ΦΕΚ Β 1759/27.03.2026."},{"title":"Νόμος 5163/2024 (Κωδικοποιημένος) - kodiko.gr","url":"https://www.kodiko.gr/nomothesia/document/1087761/nomos-5163-2024","confirms":"Στοιχεία δημοσίευσης: ΦΕΚ Α 199/06.12.2024."},{"title":"Επώνυμη καταγγελία στην Επιθεώρηση Εργασίας - Gov.gr","url":"https://www.gov.gr/upourgeia/oloi-foreis/epitheorese-ergasias/eponume-kataggelia","confirms":"Επώνυμη καταγγελία κατά επιχείρησης για παραβιάσεις της εργατικής νομοθεσίας, με κωδικούς των ηλεκτρονικών υπηρεσιών της Επιθεώρησης Εργασίας."},{"title":"Ανώνυμη Καταγγελία - Επιθεώρηση Εργασίας","url":"https://www.hli.gov.gr/odigies-ilektronikon-ypiresion/ergasiakes-scheseis-ilektronikes-ypiresies/anonymi-katangelia/","confirms":"Καταγγελία χωρίς εγγραφή, ανώνυμα ή επώνυμα. Σημείωση ελέγχου: το WebFetch απέτυχε με σφάλμα πιστοποιητικού TLS· η σελίδα φόρτωσε κανονικά σε browser και με curl (HTTP 200)."},{"title":"ΦΕΚ Α΄ 121/11.07.2025 — Κώδικας Εργατικού Δικαίου (π.δ. 62/2025)","url":"https://gslegal.gov.gr/wp-content/uploads/2025/07/%CE%91-121.pdf","confirms":"Άρθρο 402: προσαύξηση προϋπηρεσίας για όσους αμείβονται με τον κατώτατο μισθό (υπάλληλοι 10% ανά τριετία έως 3, εργατοτεχνίτες 5% ανά τριετία έως 6) και συμψηφισμός αν οι αποδοχές είναι ήδη μεγαλύτερες. Άρθρο 141: νομοθετημένος κατώτατος μισθός."}]'::jsonb, '2026-09-14'::date, true, now()),
  ('parakratisi-forou-2026-neoi-goneis', 140, 'work', 'Έλεγξε την παρακράτηση φόρου στη μισθοδοσία σου', array['μισθωτός', 'νέος έως 25', 'γονιός']::text[], 'Βλέπεις νωρίς αν ο φόρος που σου κρατούν κάθε μήνα ακολουθεί τη νέα κλίμακα για νέους και για γονείς.', 'Ν. 5246/2025', '/tekmiria/nomoi', '["Η νέα κλίμακα ισχύει για εισοδήματα από το φορολογικό έτος 2026, και ο φόρος που κρατιέται από τον μηνιαίο μισθό υπολογίζεται με βάση αυτή την κλίμακα (Ν. 5246/2025, άρθρα 3 και 47).","Αν είσαι έως 25 ετών, ο συντελεστής για φορολογητέο εισόδημα έως 20.000 € είναι 0%. Αν είσαι 26 έως 30 ετών, είναι 9%, ή 0% αν έχεις 4 ή περισσότερα εξαρτώμενα παιδιά (Ν. 5246/2025, άρθρο 3).","Αν έχεις εξαρτώμενα παιδιά, ο συντελεστής για εισόδημα από 10.000,01 έως 20.000 € είναι 18% με 1 παιδί, 16% με 2 και 9% με 3, αντί για 20%. Με 4 ή περισσότερα παιδιά είναι 0% έως τις 20.000 €. Μειώνεται επίσης ο συντελεστής για εισόδημα από 20.000,01 έως 30.000 € (Ν. 5246/2025, άρθρο 3).","Σύγκρινε τον φόρο που κρατήθηκε στις μισθοδοσίες του 2026 με τις παλιότερες. Αν δεν βλέπεις αλλαγή, ρώτα το λογιστήριο αν έχει σωστά την ηλικία σου και τον αριθμό των εξαρτώμενων παιδιών σου.","Μετά τη δήλωση φορολογίας εισοδήματος (Ε1) για τα εισοδήματα του 2026, έλεγξε το εκκαθαριστικό σημείωμα στο gov.gr με τους κωδικούς σου στο Taxisnet."]'::jsonb, 'Οι συντελεστές ισχύουν ανά κλιμάκιο εισοδήματος, όχι σε ολόκληρο τον μισθό: ό,τι είναι πάνω από 20.000 € φορολογείται με τους υπόλοιπους συντελεστές. Ο φόρος που κρατιέται κάθε μήνα είναι προσωρινός. Ο τελικός φόρος βγαίνει με το εκκαθαριστικό και μπορεί να είναι μεγαλύτερος. Για τη δική σου περίπτωση, ρώτα λογιστή.', null, null, 'https://www.gov.gr/upourgeia/oloi-foreis/anexartete-arkhe-demosion-esodon-aade/delose-phorologias-eisodematos-php-e1-e2-e3', '[{"title":"ΦΕΚ Α΄ 198/11.11.2025 - Ν. 5246/2025 (αρχείο στον ιστότοπο της ΑΑΔΕ)","url":"https://www.aade.gr/sites/default/files/2025-11/%CE%91%CE%A0%CE%9F%CE%A3%CE%A0%CE%91%CE%A3%CE%9C%CE%91%20%CE%A6%CE%95%CE%9A%20%CE%91%20198_2025%20%CE%9D%205246_2025.pdf","confirms":"Άρθρο 3 (άρθρο 15 παρ. 1 ΚΦΕ): κλίμακα 9% έως 10.000 €, 20% έως 20.000 €, 26% έως 30.000 €, 34% έως 40.000 €, 39% έως 60.000 €, 44% πάνω από 60.000 €· στο κλιμάκιο 10.000,01-20.000 € 18%, 16%, 9% για 1, 2, 3 εξαρτώμενα τέκνα· 0% στα δύο πρώτα κλιμάκια με 4 ή περισσότερα τέκνα· στο κλιμάκιο 20.000,01-30.000 € 24%, 22%, 20%, 18% για 1 έως 4 τέκνα και μείον 2 μονάδες για κάθε επιπλέον τέκνο· για φορολογητέο εισόδημα έως 20.000 € 0% για φορολογούμενους έως 25 ετών και 9% για 26 έως 30 ετών (0% αν ισχύουν 4 ή περισσότερα τέκνα). Άρθρο 60 παρ. 1 ΚΦΕ: ο μηνιαίος μισθός υπόκειται σε παρακράτηση με βάση την παρ. 1 του άρθρου 15. Άρθρο 47 παρ. 3: το άρθρο 3 ισχύει για εισοδήματα από το φορολογικό έτος 2026."},{"title":"Ο. 3068/18-11-2025 | ΑΑΔΕ","url":"https://www.aade.gr/egkyklioi-kai-apofaseis/o-3068-18-11-2025","confirms":"Εγκύκλιος της ΑΑΔΕ που κοινοποιεί διατάξεις του ν. 5246/2025, μεταξύ άλλων το άρθρο 3 για τη μείωση του φόρου εισοδήματος φυσικών προσώπων."},{"title":"Εγκύκλιος ΑΑΔΕ Ο. 3068/18.11.2025 (PDF)","url":"https://www.aade.gr/sites/default/files/2025-11/O3068_2025.pdf","confirms":"Επαναλαμβάνει τους μειωμένους συντελεστές για εξαρτώμενα τέκνα, το 0% για φορολογούμενους έως 25 ετών και το 9% για 26 έως 30 ετών για φορολογητέο εισόδημα έως 20.000 €, την παρακράτηση στον μηνιαίο μισθό και ότι το άρθρο 3 ισχύει για εισοδήματα από το φορολογικό έτος 2026."},{"title":"Νόμος 5246/2025 (Κωδικοποιημένος) - kodiko.gr","url":"https://www.kodiko.gr/nomothesia/document/1236646/nomos-5246-2025","confirms":"Στοιχεία δημοσίευσης: ΦΕΚ Α 198/11.11.2025."},{"title":"Δήλωση φορολογίας εισοδήματος ΦΠ (Ε1-Ε2-Ε3) - Gov.gr","url":"https://www.gov.gr/upourgeia/oloi-foreis/anexartete-arkhe-demosion-esodon-aade/delose-phorologias-eisodematos-php-e1-e2-e3","confirms":"Υποβολή αρχικής ή τροποποιητικής δήλωσης Ε1 και προβολή και εκτύπωση εκκαθαριστικών σημειωμάτων, με προσωπικούς κωδικούς Taxisnet. Το περιεχόμενο αποδίδεται με JavaScript· επιβεβαιώθηκε και σε browser."}]'::jsonb, '2026-09-14'::date, true, now()),
  ('arogi-aitisi-meta-katastrofi', 210, 'home', 'Έλεγξε στο arogi.gov.gr αν μπορείς να κάνεις αίτηση', array['ιδιοκτήτης σπιτιού', 'ενοικιαστής']::text[], 'Αν το σπίτι σου χτυπήθηκε από σεισμό, πλημμύρα ή φωτιά, βρίσκεις πού γίνεται η αίτηση για κρατική βοήθεια και πώς μαθαίνεις την προθεσμία για την καταστροφή που σε αφορά.', 'Ν. 5329/2026 (άρθρα 11, 23, 25 παρ. 3, 42)', '/tekmiria/nomoi', '["Άνοιξε το arogi.gov.gr και πήγαινε στην ενότητα «Αιτήσεις». Εκεί φαίνεται αν υπάρχει ανοιχτή αίτηση για την καταστροφή που σε αφορά.","Για την «πρώτη αρωγή», η αίτηση γίνεται μέσα από τη σελίδα της ΑΑΔΕ (aade.gr/arogi).","Για επιδότηση προσωρινής στέγασης, ή για άδεια επισκευής και στεγαστική συνδρομή αν είσαι ιδιοκτήτης, η αίτηση γίνεται στο arogi.services.gov.gr.","Οι αιτήσεις γίνονται μόνο όταν το κράτος ενεργοποιήσει τα μέτρα για τη συγκεκριμένη καταστροφή, με απόφαση στο ΦΕΚ, και έχουν προθεσμία. Αν δεν δεις ανοιχτή αίτηση, μην περιμένεις: η σελίδα μπορεί να μην έχει ενημερωθεί. Ρώτα τη Διεύθυνση Κρατικής Αρωγής στο 213 133 1300 ή στο infoarogi@civilprotection.gr αν βγήκε απόφαση για την περιοχή σου και ποια είναι η προθεσμία. Μέχρι τότε φωτογράφισε τις ζημιές, κράτα αποδείξεις και ρώτα αν χρειάζεται αυτοψία πριν ξεκινήσεις επισκευές."]'::jsonb, 'Οι νέοι κανόνες του Ν. 5329/2026 (αίτηση μέσω e-Άδειες, πληρωμή σε δόσεις, ακατάσχετη στεγαστική αρωγή) ισχύουν μόνο για καταστροφές μετά από ειδική κοινή υπουργική απόφαση, που δεν είχε βγει έως 14.9.2026. Για παλιότερες καταστροφές ισχύει η απόφαση για τη δική σου περιοχή. Κοινή προθεσμία δεν υπάρχει και μπορεί να είναι σύντομη: για τις πυρκαγιές του Ιουλίου 2026 η αίτηση αυτοψίας είχε προθεσμία 1 μήνα.', null, null, 'https://arogi.gov.gr/aitiseis/', '[{"title":"Κρατική Αρωγή – Αιτήσεις (arogi.gov.gr)","url":"https://arogi.gov.gr/aitiseis/","confirms":"Τα τρία κανάλια αίτησης: πρώτη αρωγή μέσω ΑΑΔΕ (aade.gr/arogi), επιδότηση προσωρινής στέγασης και «Αίτηση για άδεια επισκευής και στεγαστική συνδρομή» μέσω arogi.services.gov.gr· οι αιτήσεις γίνονται «εφόσον έχουν ενεργοποιηθεί τα συγκεκριμένα μέτρα για το εν λόγω συμβάν»· σήμερα η σελίδα γράφει «Δεν υπάρχουν ενεργές αιτήσεις»."},{"title":"Κρατική Αρωγή – αρχική σελίδα","url":"https://arogi.gov.gr/","confirms":"Επίσημος ιστότοπος κρατικής αρωγής του Υπουργείου Κλιματικής Κρίσης και Πολιτικής Προστασίας, με ενότητες Αιτήσεις, Στεγαστική Αρωγή, Συχνές Ερωτήσεις."},{"title":"ΑΑΔΕ – Κρατική Αρωγή για τους πληγέντες από φυσικές καταστροφές","url":"https://www.aade.gr/arogi","confirms":"Η σελίδα της ΑΑΔΕ από όπου γίνεται η αίτηση πρώτης αρωγής."},{"title":"gov.gr – Κρατική Αρωγή για τους πληγέντες από φυσικές καταστροφές","url":"https://arogi.services.gov.gr/","confirms":"Η ψηφιακή υπηρεσία του gov.gr για αιτήσεις προσωρινής στέγασης, άδειας επισκευής και στεγαστικής συνδρομής φορτώνει."},{"title":"Ν. 5329/2026 (ΦΕΚ Α΄ 134/4.9.2026) – πλήρες κείμενο","url":"https://www.e-nomothesia.gr/kat-politike-prostasia-psea-pallaike-amyna/nomos-5329-2026.html","confirms":"Άρθρο 25 παρ. 3: μέχρι να λειτουργήσει η νέα πλατφόρμα, για την πρώτη αρωγή χρησιμοποιείται η πλατφόρμα «arogi.gov.gr». Άρθρο 11 παρ. 2 και 5: η στεγαστική αρωγή θα γίνεται αποκλειστικά μέσω «e-Άδειες», η λειτουργία του οποίου διαπιστώνεται με κοινή υπουργική απόφαση. Άρθρο 42 παρ. 2: τα άρθρα 6 έως 14 ισχύουν από τη δημοσίευση αυτής της απόφασης και για καταστροφές μετά από αυτή. Άρθρο 8 παρ. 2: η στεγαστική αρωγή είναι αφορολόγητη, ακατάσχετη και δεν συμψηφίζεται με χρέη. Άρθρο 12: πληρωμή σε δόσεις. Άρθρο 6 παρ. 7 γ: εξαιρούνται κτίρια επιχειρήσεων που έχουν υποχρέωση ασφάλισης. Άρθρο 23 παρ. 2 α: η προθεσμία ορίζεται με κοινή υπουργική απόφαση."},{"title":"ΚΥΑ 63807/Δ.Α.Ε.Φ.Κ.-Κ.Ε./Α325/2026 (ΦΕΚ Β΄ 5250/24.8.2026) — στεγαστική συνδρομή για τις πυρκαγιές Ιουλίου-Αυγούστου 2026","url":"https://www.e-nomothesia.gr/kat-pyrkagies-emprismoi-purosbestiko-soma/koine-upourgike-apophase-63807-daephk-kea-325-2026.html","confirms":"Αίτηση για αυτοψία του κτιρίου μέσα σε 1 μήνα από τη δημοσίευση και αίτηση για άδεια επισκευής μέσα σε 6 μήνες."}]'::jsonb, '2026-09-14'::date, true, now()),
  ('nea-taftotita-prin-to-taxidi', 220, 'home', 'Κλείσε ραντεβού για νέα ταυτότητα πριν ταξιδέψεις', array['όλοι', 'γονιός', 'Έλληνας εξωτερικού']::text[], 'Από τις 3.8.2026 η παλιά ταυτότητα δεν ισχύει ως ταξιδιωτικό έγγραφο για άλλη χώρα. Μαθαίνεις πώς κλείνεις ραντεβού για τη νέα.', 'Κανονισμός (ΕΕ) 2025/1208 του Συμβουλίου, άρθρο 5', '/tekmiria/epitirisi', '["Μπες στην υπηρεσία «Ραντεβού για την έκδοση δελτίου ταυτότητας Ελλήνων πολιτών» στο gov.gr με τους κωδικούς σου Taxisnet.","Διάλεξε όποια αστυνομική υπηρεσία θέλεις, ανεξάρτητα από το πού μένεις, και ημερομηνία. Τα διαθέσιμα ραντεβού καλύπτουν τις επόμενες 90 ημέρες, οπότε μην το αφήσεις για την τελευταία στιγμή.","Πριν πας, πλήρωσε το ηλεκτρονικό παράβολο των 10 ευρώ (5 ευρώ αν είσαι πολύτεκνος). Φωτογραφία βγάζεις στην υπηρεσία ή σε πιστοποιημένο φωτογράφο που την ανεβάζει στο myPhoto.","Μπορείς να κλείσεις ραντεβού και για το παιδί σου, αν είναι πάνω από 12 ετών."]'::jsonb, 'Αν μένεις στο εξωτερικό, αίτηση για νέα ταυτότητα γίνεται μόνο στην Ελλάδα, στην Ελληνική Αστυνομία· στο προξενείο μπορείς να ζητήσεις διαβατήριο. Αν είσαι ήδη στο εξωτερικό με παλιά ταυτότητα, ρώτα το ελληνικό προξενείο πώς θα επιστρέψεις. Για απώλεια ή κλοπή ισχύουν άλλα βήματα.', null, null, 'https://www.gov.gr/el/services/1001790/id', '[{"title":"gov.gr – Ραντεβού για την έκδοση δελτίου ταυτότητας Ελλήνων πολιτών","url":"https://www.gov.gr/el/services/1001790/id","confirms":"Ψηφιακό ραντεβού για έκδοση ταυτότητας με φυσική παρουσία στην αστυνομική υπηρεσία· χρειάζονται οι προσωπικοί κωδικοί Taxisnet· «Τα ραντεβού που διατίθενται αφορούν το χρονικό διάστημα των επόμενων 90 ημερών»· ραντεβού και για ανήλικο τέκνο άνω των 12 ετών. (Το id.gov.gr και η παλιά διεύθυνση gov.gr ανακατευθύνουν εδώ.)"},{"title":"Ελληνική Αστυνομία – Έκδοση Δελτίου Ταυτότητας","url":"https://www.astynomia.gr/odigos-tou-politi/dikaiologitika/ekdosi-deltiou-taftotitas/","confirms":"«Ηλεκτρονικό παράβολο ύψους 10,00€», μισό (5,00€) για πολύτεκνους· το παράβολο πρέπει να έχει πληρωθεί πριν την προσέλευση· φωτογραφία στην Αρχή έκδοσης ή από πιστοποιημένο φωτογράφο μέσω myPhoto· ραντεβού και για ανήλικα τέκνα άνω των 12 ετών."},{"title":"Πρεσβεία της Ελλάδας στην Ιρλανδία (mfa.gr) – Το δελτίο αστυνομικής ταυτότητας παλαιού τύπου παύει να ισχύει ως ταξιδιωτικό έγγραφο (6.5.2026)","url":"https://www.mfa.gr/missionsabroad/el/ireland/news/semantike-enemerose-to-deltio-astunomikes-tautotetas-palaiou-tupou-pauei-na-iskhuei-os-taxidiotiko-eggrapho-2.html","confirms":"«μετά τις 03/08/2026 το δελτίο αστυνομικής ταυτότητας παλαιού τύπου παύει να ισχύει ως ταξιδιωτικό έγγραφο»· το αίτημα για νέα ταυτότητα υποβάλλεται μόνο στην Ελλάδα (Ελληνική Αστυνομία) μέσω gov.gr· αίτηση διαβατηρίου μπορεί να γίνει σε προξενική αρχή."},{"title":"Γενικό Προξενείο Γενεύης (mfa.gr) – Λήξη ισχύος δελτίων αστυνομικών ταυτοτήτων παλαιού τύπου (17.6.2026)","url":"https://www.mfa.gr/switzerland/geniko-proxeneio-geneva/news/lexe-iskhuos-deltion-astunomikon-tautoteton-palaiou-tupou.html","confirms":"Επιβεβαιώνει ότι μετά τις 3.8.2026 η παλαιού τύπου ταυτότητα δεν ισχύει ως ταξιδιωτικό έγγραφο και ότι η νέα ταυτότητα ζητείται μόνο στην Ελλάδα."},{"title":"Κανονισμός (ΕΕ) 2025/1208 του Συμβουλίου (EUR-Lex)","url":"https://eur-lex.europa.eu/legal-content/EL/TXT/HTML/?uri=CELEX:32025R1208","confirms":"Άρθρο 5 παρ. 2 α: τα δελτία ταυτότητας χωρίς λειτουργική μηχαναγνώσιμη ζώνη παύουν να ισχύουν κατά τη λήξη τους ή το αργότερο στις 3 Αυγούστου 2026."}]'::jsonb, '2026-09-14'::date, true, now()),
  ('prosopikos-arithmos-myinfo', 230, 'home', 'Βρες τον Προσωπικό σου Αριθμό στο myInfo', array['όλοι', 'Έλληνας εξωτερικού']::text[], 'Έχεις έτοιμο τον αριθμό με τον οποίο σε ταυτοποιεί το Δημόσιο. Αν η ταυτότητά σου γράφει αυτόν τον αριθμό, δεν χρειάζεται να δίνεις φωτοτυπία της σε δημόσιες υπηρεσίες.', 'Ν. 4727/2020 (άρθρο 11) και Ν. 5099/2024 (άρθρο 31, όπως τροποποιήθηκε με το άρθρο 18 του Ν. 5305/2026)', '/tekmiria/epitirisi', '["Μπες στο pa.gov.gr και πάτα για είσοδο στην εφαρμογή myInfo με τους κωδικούς σου TAXISnet.","Γράψε τον κωδικό μίας χρήσης που θα έρθει στο κινητό σου (πρέπει να είναι πιστοποιημένο στο ΕΜΕπ). Επιβεβαίωσε τα στοιχεία σου και δες τον Προσωπικό σου Αριθμό.","Αν δεν έχεις κωδικούς TAXISnet ή πιστοποιημένο κινητό, πήγαινε αυτοπροσώπως σε ΚΕΠ. Αν μένεις στο εξωτερικό, πήγαινε σε έμμισθη προξενική αρχή.","Αν η ταυτότητά σου γράφει Προσωπικό Αριθμό, η δημόσια υπηρεσία δεν πρέπει να σου ζητά φωτοτυπία της: βγάζει η ίδια ψηφιακό αντίγραφο. Αν σου τη ζητήσουν, ανέφερε τον κανόνα, αλλά μη χάσεις προθεσμία για αυτό."]'::jsonb, 'Ο κανόνας για τη φωτοτυπία αφορά τις δημόσιες υπηρεσίες και τις ταυτότητες που γράφουν Προσωπικό Αριθμό· με ιδιωτικές εταιρείες, όπως τράπεζες, έλεγξε τι ζητούν.', null, null, 'https://pa.gov.gr/', '[{"title":"myInfo – Προσωπικός Αριθμός (pa.gov.gr)","url":"https://pa.gov.gr/","confirms":"Είσοδος στο myInfo με κωδικούς TAXISnet και κωδικό μίας χρήσης σε κινητό πιστοποιημένο στο ΕΜΕπ· «Εκδίδεται αυτόματα ο Προσωπικός μου Αριθμός μετά την επιβεβαίωση των στοιχείων μου»· «Αναγραφή στα νέα δελτία ταυτότητας. Κατάργηση προσκόμισης φωτοαντιγράφου για χρήση στον δημόσιο τομέα». (Το myinfo.gov.gr ανακατευθύνει εδώ με 308.)"},{"title":"pa.gov.gr – Συχνές ερωτήσεις","url":"https://pa.gov.gr/syxnes-erotiseis/","confirms":"Ο αριθμός φαίνεται στο myInfo, με αυτοπρόσωπο αίτημα σε ΚΕΠ ή έμμισθη Προξενική Αρχή, και στο wallet.gov.gr· δεν χρειάζεται να βγάλεις ξανά ταυτότητα αν η δική σου δεν τον γράφει· νομική βάση: άρθρο 11 Ν. 4727/2020 και ΠΔ 40/2025."},{"title":"Lawspot – Άρθρο 11 Ν. 4727/2020: Προσωπικός Αριθμός","url":"https://www.lawspot.gr/nomothesia/n-4727-2020/arthro-11-nomos-4727-2020-prosopikos-arithmos/","confirms":"Ο Προσωπικός Αριθμός καθιερώνεται «ως αριθμός υποχρεωτικής επαλήθευσης της ταυτότητας» στις συναλλαγές με τον δημόσιο τομέα."},{"title":"Ν. 5305/2026 (ΦΕΚ Α΄ 85/29.5.2026) – πλήρες κείμενο","url":"https://www.e-nomothesia.gr/kat-demosia-dioikese/nomos-5305-2026.html","confirms":"Άρθρο 18: αντικαθιστά το άρθρο 31 του Ν. 5099/2024 (Α΄48). Στις συναλλαγές με τον δημόσιο τομέα που απαιτούν φωτοαντίγραφο ταυτότητας, το ψηφιακό αντίγραφο εκδίδεται αποκλειστικά μέσω της ψηφιακής υπηρεσίας από δημοσίους υπαλλήλους· «Η υποβολή φωτοαντιγράφου ... επιτρέπεται μόνο εφόσον στο δελτίο δεν αναγράφεται ο προσωπικός αριθμός». Άρθρο 43: ισχύς από τη δημοσίευση. Άρθρο 16: για τον ιδιωτικό τομέα «επιτρέπονται» ψηφιακά αντίγραφα, με εξουσιοδότηση για κοινή υπουργική απόφαση στο άρθρο 17."},{"title":"Εθνικό Μητρώο Διοικητικών Διαδικασιών (mitos.gov.gr) – Ψηφιακό αντίγραφο δελτίου ταυτότητας Ελλήνων πολιτών","url":"https://mitos.gov.gr/index.php/%CE%94%CE%94:%CE%A8%CE%B7%CF%86%CE%B9%CE%B1%CE%BA%CF%8C_%CE%B1%CE%BD%CF%84%CE%AF%CE%B3%CF%81%CE%B1%CF%86%CE%BF_%CE%B4%CE%B5%CE%BB%CF%84%CE%AF%CE%BF%CF%85_%CF%84%CE%B1%CF%85%CF%84%CF%8C%CF%84%CE%B7%CF%84%CE%B1%CF%82_%CE%95%CE%BB%CE%BB%CE%AE%CE%BD%CF%89%CE%BD_%CF%80%CE%BF%CE%BB%CE%B9%CF%84%CF%8E%CE%BD","confirms":"Επίσημη διαδικασία για το ψηφιακό αντίγραφο ταυτότητας στις δημόσιες υπηρεσίες, με κανάλι το id-copy.services.gov.gr."},{"title":"gov.gr – Ψηφιακό αντίγραφο δελτίου ταυτότητας","url":"https://id-copy.services.gov.gr/","confirms":"«Το ψηφιακό αντίγραφο δελτίου ταυτότητας εκδίδεται αποκλειστικά για τις συναλλαγές φυσικών προσώπων με φορείς του δημόσιου τομέα, για τη διεκπεραίωση των οποίων υπάρχει υποχρέωση υποβολής φωτοαντιγράφου δελτίου ταυτότητας.»"}]'::jsonb, '2026-09-14'::date, true, now()),
  ('taftotita-sto-kinito-gov-gr-wallet', 240, 'home', 'Βάλε ταυτότητα και δίπλωμα στο Gov.gr Wallet', array['όλοι']::text[], 'Μπορείς να δείξεις την ταυτότητα ή το δίπλωμά σου από το κινητό, όταν σου τα ζητούν μέσα στην Ελλάδα, αρκεί το κινητό να λειτουργεί.', 'Ν. 4954/2022 (άρθρο 80) και Ν. 4727/2020 (άρθρα 24, 27)', '/tekmiria/nomoi', '["Κατέβασε την εφαρμογή Gov.gr Wallet (δες το wallet.gov.gr). Συνδέσου με τους κωδικούς TAXISnet ή του web banking. Για να βάλεις ταυτότητα ή δίπλωμα, το κινητό σου πρέπει να είναι πιστοποιημένο στο Εθνικό Μητρώο Επικοινωνίας (ΕΜΕπ).","Γράψε τον κωδικό μίας χρήσης που έρχεται στο κινητό σου και πρόσθεσε την ταυτότητα ή το δίπλωμα οδήγησης. Για κάθε έγγραφο θα σου ζητηθεί νέος κωδικός.","Όταν σου ζητήσουν ταυτότητα, δείξε τον κωδικό QR. Ο υπάλληλος τον σκανάρει και του λες τον αριθμό ασφαλείας που έρχεται στο κινητό σου."]'::jsonb, 'Η ψηφιακή ταυτότητα και το ψηφιακό δίπλωμα ισχύουν μόνο μέσα στην Ελλάδα και δεν είναι ταξιδιωτικά έγγραφα: για ταξίδι σε άλλη χώρα χρειάζεσαι κανονική ταυτότητα νέου τύπου ή διαβατήριο. Αν το κινητό κλείσει ή δεν έχει σύνδεση, δεν μπορείς να τα δείξεις. Όταν οδηγείς, καλό είναι να έχεις μαζί και το κανονικό δίπλωμα.', null, null, 'https://wallet.gov.gr/', '[{"title":"Gov.gr Wallet","url":"https://wallet.gov.gr/","confirms":"Η επίσημη σελίδα της υπηρεσίας Gov.gr Wallet φορτώνει."},{"title":"Υπουργείο Ψηφιακής Διακυβέρνησης – Εγκύκλιος 27.7.2022 (ΑΠ 4090) για την ταυτοποίηση μέσω της εφαρμογής του άρθρου 80 Ν. 4954/2022","url":"https://wallet.gov.gr/27_7_egkyklios_walletid.pdf","confirms":"Η εφαρμογή αποθηκεύει στοιχεία ταυτότητας ή άδειας οδήγησης. Σύνδεση με κωδικούς ΓΓΠΣΔΔ ή e-banking και κωδικό μίας χρήσης, με νέο κωδικό για κάθε έγγραφο. Επίδειξη με QR και αριθμό ασφαλείας 4 ψηφίων. Η επίδειξη «ισοδυναμεί με επίδειξη του αντίστοιχου φυσικού ταυτοποιητικού εγγράφου» και ο πολίτης «δεν υποχρεούται ... να φέρει μαζί του» το φυσικό έγγραφο, για ταυτοποίηση μεταξύ άλλων από φορείς του δημόσιου τομέα και δικαστικές αρχές."},{"title":"Ν. 5305/2026 (ΦΕΚ Α΄ 85/29.5.2026) – πλήρες κείμενο","url":"https://www.e-nomothesia.gr/kat-demosia-dioikese/nomos-5305-2026.html","confirms":"Το άρθρο 16 παρ. 2 αναφέρεται στο «ψηφιακό αποθετήριο του άρθρου 80 του ν. 4954/2022», άρα το πλαίσιο του wallet ισχύει και το 2026."}]'::jsonb, '2026-09-14'::date, true, now()),
  ('adeia-politikou-gamou-gov-gr', 250, 'home', 'Ζήτα άδεια πολιτικού γάμου ψηφιακά από το gov.gr', array['όλοι']::text[], 'Ζητάς την άδεια πολιτικού γάμου ψηφιακά, χωρίς ουρά στον δήμο. Η διαδικασία είναι ίδια για κάθε ζευγάρι.', 'Ν. 5089/2024', '/tekmiria/nomoi', '["Πρώτα δημοσίευσε τα στοιχεία του γάμου σε ημερήσια εφημερίδα του τόπου όπου μένεις.","Χρειάζεται άδεια γάμου για τον καθένα σας, από τον δήμο όπου μένει. Μπες στην υπηρεσία «Άδεια πολιτικού γάμου» στο gov.gr με τους κωδικούς Taxisnet. Πρέπει πρώτα το κινητό σου να είναι πιστοποιημένο στο Εθνικό Μητρώο Επικοινωνίας (ΕΜΕπ). Επισύναψε ολόκληρη τη σελίδα της εφημερίδας με τη δημοσίευση και ένα αποδεικτικό κατοικίας (π.χ. δήλωση εφορίας ή λογαριασμό ρεύματος). Αν μένετε σε διαφορετικούς δήμους, βεβαιωθείτε ότι έχει βγει άδεια και για τους δύο.","Η άδεια εκδίδεται όχι νωρίτερα από 7 ημερολογιακές ημέρες και έρχεται στη θυρίδα σου στο gov.gr. Θα ενημερωθείς με email και SMS. Μην κλείσεις ημερομηνία τελετής πριν έχεις την άδεια στα χέρια σου.","Κλείστε με τον δήμο όπου θα γίνει ο γάμος ημέρα, ώρα και τόπο. Ο δήμος μπορεί να ζητήσει τέλος. Την ημέρα του γάμου φέρτε τις άδειες και των δύο, ταυτότητα ή διαβατήριο, και δύο μάρτυρες άνω των 18 ετών."]'::jsonb, 'Η ψηφιακή αίτηση στο gov.gr είναι για Έλληνες πολίτες που μένουν στην Ελλάδα και παντρεύονται Έλληνα πολίτη. Σε άλλη περίπτωση, ή αν ο δήμος σου δεν δέχεται την αίτηση ψηφιακά, ρώτα τον δήμο σου.', 'Η άδεια γάμου ισχύει 6 μήνες. Αν ο γάμος δεν γίνει μέσα σε 6 μήνες από τη δημοσίευση στην εφημερίδα, πρέπει να δημοσιεύσεις ξανά.', 'https://mitos.gov.gr/index.php/%CE%94%CE%94:%CE%86%CE%B4%CE%B5%CE%B9%CE%B1_%CF%80%CE%BF%CE%BB%CE%B9%CF%84%CE%B9%CE%BA%CE%BF%CF%8D_%CE%B3%CE%AC%CE%BC%CE%BF%CF%85', 'https://www.gov.gr/el/services/1001451/adeia-politikou-gamou', '[{"title":"gov.gr – Άδεια πολιτικού γάμου","url":"https://www.gov.gr/el/services/1001451/adeia-politikou-gamou","confirms":"«Μπορείτε να αιτηθείτε στον Δήμο κατοικίας σας, την έκδοση άδειας γάμου». Προϋποθέσεις: Έλληνας πολίτης, νόμιμη κατοικία στην Ελλάδα, γάμος στην Ελλάδα με Έλληνα πολίτη, δημοσίευση σε ημερήσια εφημερίδα. Αποδεικτικό κατοικίας: δήλωση φορολογίας εισοδήματος ή λογαριασμός κοινής ωφέλειας. «Η άδεια πολιτικού γάμου εκδίδεται μετά από 7 ημερολογιακές ημέρες» και στέλνεται στη θυρίδα με email και SMS. (Η παλιά διεύθυνση gov.gr/ipiresies/... ανακατευθύνει εδώ με 301.)"},{"title":"Εθνικό Μητρώο Διοικητικών Διαδικασιών (mitos.gov.gr) – Άδεια πολιτικού γάμου","url":"https://mitos.gov.gr/index.php/%CE%94%CE%94:%CE%86%CE%B4%CE%B5%CE%B9%CE%B1_%CF%80%CE%BF%CE%BB%CE%B9%CF%84%CE%B9%CE%BA%CE%BF%CF%8D_%CE%B3%CE%AC%CE%BC%CE%BF%CF%85","confirms":"Στη νομική βάση περιλαμβάνεται ο «Νόμος 3 5089 2024 27 Α» και η περίπτωση «Σύναψη γάμου από άτομα του ίδιου φύλου». Έκδοση σε «7 ημέρες», ισχύς «6 μήνες», «Παρέχεται χωρίς κόστος», ψηφιακό κανάλι στο gov.gr."},{"title":"Εθνικό Μητρώο Διοικητικών Διαδικασιών (mitos.gov.gr) – Τέλεση πολιτικού γάμου για πρόσωπα ιδίου φύλου","url":"https://mitos.gov.gr/index.php/%CE%94%CE%94:%CE%A4%CE%AD%CE%BB%CE%B5%CF%83%CE%B7_%CF%80%CE%BF%CE%BB%CE%B9%CF%84%CE%B9%CE%BA%CE%BF%CF%8D_%CE%B3%CE%AC%CE%BC%CE%BF%CF%85_%CE%B3%CE%B9%CE%B1_%CF%80%CF%81%CF%8C%CF%83%CF%89%CF%80%CE%B1_%CE%B9%CE%B4%CE%AF%CE%BF%CF%85_%CF%86%CF%8D%CE%BB%CE%BF%CF%85","confirms":"Νομική βάση ο Ν. 5089/2024. «Δεν παρέχεται ψηφιακά» και κατάθεση «αποκλειστικά δια ζώσης». Χρειάζονται οι πρωτότυπες άδειες γάμου και των δύο, εξάμηνης ισχύος, ταυτοποιητικό έγγραφο και δύο μάρτυρες άνω των 18 ετών. Τον γάμο τελεί ο Δήμαρχος ή ο νόμιμος αναπληρωτής του."},{"title":"Υπουργείο Εσωτερικών – Ψηφιακά η έκδοση άδειας πολιτικού γάμου","url":"https://www.ypes.gr/psifiaka-i-ekdosi-adeias-politikou-gamou/","confirms":"Η αίτηση γίνεται στο gov.gr (ενότητα «Οικογένεια», «Γάμος / συμβίωση») με κωδικούς Taxisnet ή web banking, με επισύναψη της δημοσίευσης και αποδεικτικού κατοικίας· η άδεια εκδίδεται μετά από 7 ημερολογιακές ημέρες."},{"title":"Ν. 5089/2024 (ΦΕΚ Α΄ 27/16.2.2024) – Ισότητα στον πολιτικό γάμο","url":"https://www.e-nomothesia.gr/oikogeneia/n-5089-2024.html","confirms":"Τίτλος νόμου και ΦΕΚ 27/Α/16-2-2024."}]'::jsonb, '2026-09-14'::date, true, now()),
  ('prolamvano-dorean-proliptikes', 310, 'health', 'Έλεγξε αν δικαιούσαι δωρεάν προληπτική εξέταση', array['όλοι']::text[], 'Μπορεί να κάνεις δωρεάν προληπτικό έλεγχο για σοβαρές ασθένειες, αντί να πληρώσεις την εξέταση από την τσέπη σου.', 'Εθνικό Πρόγραμμα Πρόληψης «Προλαμβάνω» (Υπουργείο Υγείας)', '/tekmiria/ygeia', '["Έλεγξε αν έλαβες SMS ή άυλο παραπεμπτικό για δωρεάν προληπτική εξέταση. Το Υπουργείο Υγείας ανακοίνωσε (12.6.2026) ότι το «Προλαμβάνω» ξεκινά ξανά από την 1η Σεπτεμβρίου 2026 με νέα παραπεμπτικά και συνεχίζεται έως το τέλος του 2030. Αν δεν έλαβες μήνυμα, αυτό δεν σημαίνει απαραίτητα ότι δεν σε αφορά.","Μη βασιστείς σε παλιό παραπεμπτικό. Σύμφωνα με το Υπουργείο Υγείας, τα παραπεμπτικά του προηγούμενου κύκλου μπορούσαν να χρησιμοποιηθούν μόνο έως τις 30.6.2026.","Δες στο proliptikes.gov.gr ποιες εξετάσεις καλύπτει το πρόγραμμα. Η σελίδα γράφτηκε για τον προηγούμενο κύκλο, οπότε οι ηλικίες μπορεί να αλλάξουν. Για τη δική σου περίπτωση πάρε τηλέφωνο στο 11401. Κλείσε ραντεβού σε πάροχο που συνεργάζεται με το πρόγραμμα, με τον ΑΜΚΑ σου.","Για το αν χρειάζεσαι μια εξέταση και τι σημαίνει το αποτέλεσμα, μίλησε με τον γιατρό σου."]'::jsonb, 'Η προληπτική εξέταση είναι για όσους δεν έχουν συμπτώματα. Αν έχεις ενόχληση ή σύμπτωμα, μην περιμένεις SMS ή παραπεμπτικό: πήγαινε τώρα σε γιατρό. Κάθε εξέταση αφορά συγκεκριμένες ηλικίες και τα παλιά παραπεμπτικά δεν ισχύουν πια, οπότε έλεγξε ότι έχεις ενεργό παραπεμπτικό πριν πας.', null, null, 'https://proliptikes.gov.gr/', '[{"title":"Υπουργείο Υγείας: Το «ΠΡΟΛΑΜΒΑΝΩ» συνεχίζεται. Νέα φάση του προγράμματος από τον Σεπτέμβριο 2026 έως το 2030 (12.6.2026)","url":"https://www.moh.gov.gr/articles/ministry/grafeio-typoy/press-releases/14396-to-laquo-prolambanw-raquo-synexizetai-nea-fash-toy-programmatos-apo-ton-septembrio-2026-ews-to-2030","confirms":"Οι δράσεις ξεκινούν εκ νέου από 1.9.2026 έως το 2030· ειδοποίηση με SMS και άυλα παραπεμπτικά· δωρεάν για κάθε πολίτη, ασφαλισμένο ή ανασφάλιστο."},{"title":"ΕΟΠΥΥ: Ανακοίνωση για λήξη του προγράμματος «Σπύρος Δοξιάδης» (22.6.2026, ορθή επανάληψη)","url":"https://www.eopyy.gov.gr/media/r2jhffz0/22062026_anakoinosi-gia-liksi-doksiadi_gia-anartisi_orthi-epanalipsi.pdf","confirms":"Ο τρέχων τότε κύκλος του «ΠΡΟΛΑΜΒΑΝΩ» (δράση για καρκίνο μαστού) ολοκληρώθηκε 30.6.2026· τα παραπεμπτικά μπορούσαν να εκτελεστούν έως 30.6.2026· το ραντεβού κλείνεται σε συνεργαζόμενο πάροχο."},{"title":"ΕΟΠΥΥ: Πρόληψη του Καρκίνου του Μαστού - Ψηφιακή Μαστογραφία, Πρόγραμμα «ΣΠΥΡΟΣ ΔΟΞΙΑΔΗΣ» (25.6.2026)","url":"https://www.eopyy.gov.gr/el/arthra/prolipsi-tou-karkinou-tou-mastou-psifiaki-mastografia-programma-spyros-doksiadis-25-06-2026/","confirms":"Η σελίδα του ΕΟΠΥΥ που αναρτά την ανακοίνωση λήξης του κύκλου."},{"title":"Υπουργείο Υγείας: Σημεία συνέντευξης του Υπουργού Υγείας στο ΕΡΤnews Radio (1.7.2026)","url":"https://www.moh.gov.gr/articles/ministry/grafeio-typoy/press-releases/14443-shmeia-synenteykshs-toy-ypoyrgoy-ygeias-adwni-gewrgiadh-stis-laquo-prwines-diadromes-raquo-me-toys-basilh-adamopoylo-kai-maria-gewrgioy-sto-ertnews-radio","confirms":"«Όλα τα προγράμματα του «Προλαμβάνω» ολοκληρώθηκαν στις 30 Ιουνίου.»"},{"title":"Εθνικό Πρόγραμμα Πρόληψης – Πρόγραμμα Προλαμβάνω (proliptikes.gov.gr)","url":"https://proliptikes.gov.gr/","confirms":"Επίσημη σελίδα του προγράμματος: εξετάσεις και ηλικίες ανά εξέταση, άυλο παραπεμπτικό για όσους έχουν άυλη συνταγογράφηση, ραντεβού σε συνεργαζόμενο κέντρο με ΑΜΚΑ."}]'::jsonb, '2026-09-14'::date, true, now()),
  ('lista-xeirourgeion-prin-plirosis', 320, 'health', 'Πριν πληρώσεις χειρουργείο, μάθε την ημερομηνία σου στη λίστα', array['ασθενής']::text[], 'Μαθαίνεις την προγραμματισμένη ημερομηνία της επέμβασής σου στη λίστα του ΕΣΥ, ώστε να αποφασίσεις με τον γιατρό σου αν χρειάζεται απογευματινό χειρουργείο επί πληρωμή.', 'Κοινή υπουργική απόφαση για τα χειρουργεία πέραν του τακτικού ωραρίου στα νοσοκομεία του ΕΣΥ (ΚΥΑ Γ2α/οικ.14549/2025)', '/tekmiria/ygeia', '["Όταν μπαίνεις στη λίστα για χειρουργείο σε νοσοκομείο του ΕΣΥ, ζήτα από το νοσοκομείο την προγραμματισμένη ημερομηνία της επέμβασης. Από 1.2.2024 ισχύει η Ενιαία Ψηφιακή Λίστα Χειρουργείων.","Έλεγξε το email σου και την εφαρμογή MyHealth. Σύμφωνα με το Υπουργείο Υγείας, η ΗΔΙΚΑ στέλνει την ημερομηνία του χειρουργείου με email ή μέσω του MyHealth.","Αν σου προτείνουν απογευματινό χειρουργείο επί πληρωμή, ζήτα από το νοσοκομείο γραπτά το κόστος και την ημερομηνία που έχεις στη λίστα. Ρώτα επίσης αν μπορεί να γίνει η επέμβαση χωρίς χρέωση για σένα. Μην αναβάλεις επέμβαση μόνο για να γλιτώσεις χρήματα, χωρίς να το συζητήσεις με τον γιατρό σου.","Για το αν η επέμβασή σου μπορεί να περιμένει, μίλησε με τον γιατρό σου."]'::jsonb, 'Αν η επέμβασή σου είναι επείγουσα ή τα συμπτώματα χειροτερεύουν, μίλησε αμέσως με τον γιατρό σου ή πήγαινε στα επείγοντα, όποια ημερομηνία κι αν έχεις στη λίστα. Αν δεν έχεις λάβει ημερομηνία με email ή στο MyHealth, ρώτα το νοσοκομείο πριν πληρώσεις. Για παράπονο, απευθύνσου στο Γραφείο Προστασίας Δικαιωμάτων Ληπτών Υπηρεσιών Υγείας του νοσοκομείου.', null, null, 'https://www.gov.gr/upourgeia/upourgeio-psephiakes-diakuberneses/elektronike-diakubernese-koinonikes-asphalises-edika-ae/epharmoge-gia-kinetes-suskeues-myhealth', '[{"title":"Υπουργείο Υγείας: Σε εφαρμογή από σήμερα, 1η Φεβρουαρίου, η Ενιαία Ψηφιακή Λίστα Χειρουργείων (1.2.2024)","url":"https://www.moh.gov.gr/articles/ministry/grafeio-typoy/press-releases/12149-se-efarmogh-apo-shmera-1h-febroyarioy-h-eniaia-pshfiakh-lista-xeiroyrgeiwn","confirms":"«Ο ασθενής ενημερώνεται από το νοσοκομείο για την προγραμματισμένη ημερομηνία του χειρουργείου του, πληροφορία που λαμβάνει και από την ΗΔΙΚΑ με email ή μέσω της εφαρμογής MyHealthApp»· υπεύθυνος για κατάρτιση και λειτουργία ο Διευθυντής Ιατρικής Υπηρεσίας."},{"title":"Υπουργείο Υγείας: Το πλαίσιο λειτουργίας των απογευματινών χειρουργείων (19.2.2024)","url":"https://www.moh.gov.gr/articles/ministry/grafeio-typoy/press-releases/12205-to-plaisio-leitoyrgias-twn-apogeymatinwn-xeiroyrgeiwn-paroysiasan-se-synenteyksh-typoy-o-ypoyrgos-ygeias-adwnis-gewrgiadhs-kai-o-yfypoyrgos-ygeias-marios-themistokleoys","confirms":"Στα απογευματινά χειρουργεία επί πληρωμή πληρώνει ο ασθενής που τα επιλέγει· λειτουργούν παράλληλα με την Ενιαία Λίστα Χειρουργείων."},{"title":"Υπουργείο Υγείας: ΚΥΑ για χειρουργικές επεμβάσεις πέραν του τακτικού ωραρίου λειτουργίας των νοσοκομείων του ΕΣΥ (5.3.2024)","url":"https://www.moh.gov.gr/articles/ministry/grafeio-typoy/press-releases/12235-koini-ypourgiki-apofasi-apo-ta-ypourgeia-ygeias-kai-ethnikis-oikonomias-kai-oikonomikwn-gia-xeirourgeia","confirms":"Δημοσίευση της ΚΥΑ με συνημμένο ΦΕΚ Β'' 1485/2024."},{"title":"Gov.gr: Εφαρμογή για κινητές συσκευές myHealth","url":"https://www.gov.gr/upourgeia/upourgeio-psephiakes-diakuberneses/elektronike-diakubernese-koinonikes-asphalises-edika-ae/epharmoge-gia-kinetes-suskeues-myhealth","confirms":"Επίσημη σελίδα της εφαρμογής MyHealth της ΗΔΙΚΑ στο gov.gr (φόρτωσε μόνο ο τίτλος της σελίδας στο εργαλείο ελέγχου)."},{"title":"ΚΥΑ Γ2α/οικ.14549/2025 (ΦΕΚ Β΄ 1574/01.04.2025)","url":"https://www.e-nomothesia.gr/kat-ygeia/kya-g2a-oik-14549-2025.html","confirms":"Αντικατέστησε την ΚΥΑ του ΦΕΚ Β΄ 1485/2024 για τα χειρουργεία πέραν του τακτικού ωραρίου."}]'::jsonb, '2026-09-14'::date, true, now()),
  ('elleipsi-farmakou-rota-farmakopoio', 330, 'health', 'Αν λείπει το φάρμακό σου, ρώτα τον φαρμακοποιό', array['ασθενής']::text[], 'Μπορεί να βρεθεί κατάλληλη εναλλακτική μαζί με τον φαρμακοποιό και τον γιατρό σου, χωρίς να στραφείς σε παράνομες πηγές φαρμάκων.', 'Οδηγίες του ΕΟΦ για τις ελλείψεις φαρμάκων (18.11.2025)', '/tekmiria/ygeia', '["Αν το φαρμακείο δεν έχει το φάρμακό σου, ρώτα τον φαρμακοποιό. Σύμφωνα με τον ΕΟΦ, οι φαρμακοποιοί αναζητούν κατάλληλες εναλλακτικές όταν ένα φάρμακο δεν είναι διαθέσιμο και συνεργάζονται με τον γιατρό που έγραψε τη συνταγή.","Για κάθε αλλαγή στη θεραπεία, μίλησε με τον γιατρό σου. Κατά τον ΕΟΦ, ο γιατρός γράφει εναλλακτική αγωγή όταν χρειάζεται και παρακολουθεί την αλλαγή.","Δες τη λίστα φαρμάκων με περιορισμένη διαθεσιμότητα στη σελίδα του ΕΟΦ «Παρακολούθηση επάρκειας αγοράς».","Πάρε μόνο τις συσκευασίες που χρειάζεσαι και μην αγοράζεις φάρμακα από παράνομες πηγές. Αυτό ζητά ο ΕΟΦ από τους ασθενείς."]'::jsonb, 'Μη σταματήσεις και μην αλλάξεις μόνος σου το φάρμακο. Αν πρόκειται να μείνεις χωρίς φάρμακο που δεν πρέπει να διακοπεί, πάρε τηλέφωνο αμέσως τον γιατρό σου ή πήγαινε σε εφημερεύον νοσοκομείο. Η λίστα του ΕΟΦ που βρήκαμε στις 14.9.2026 είχε ημερομηνία 30.4.2026, οπότε μπορεί να μη δείχνει τη σημερινή κατάσταση.', null, null, 'https://www.eof.gr/eparkeia-agoras/', '[{"title":"ΕΟΦ: Η αντιμετώπιση των ελλείψεων των φαρμάκων χρειάζεται ομαδική προσπάθεια (18.11.2025)","url":"https://www.eof.gr/%CE%B7-%CE%B1%CE%BD%CF%84%CE%B9%CE%BC%CE%B5%CF%84%CF%8E%CF%80%CE%B9%CF%83%CE%B7-%CF%84%CF%89%CE%BD-%CE%B5%CE%BB%CE%BB%CE%B5%CE%AF%CF%88%CE%B5%CF%89%CE%BD-%CF%84%CF%89%CE%BD-%CF%86%CE%B1%CF%81%CE%BC/","confirms":"Ασθενείς: να μην προμηθεύονται περισσότερες συσκευασίες από όσες χρειάζονται, να μη στρέφονται σε παράνομες πηγές, να συζητούν κάθε προβληματισμό με γιατρό ή φαρμακοποιό. Φαρμακοποιοί: εντοπίζουν κατάλληλες εναλλακτικές και συνεργάζονται με τους συνταγογράφους. Γιατροί: συνταγογραφούν εναλλακτική αγωγή όταν χρειάζεται και επιβλέπουν την αλλαγή."},{"title":"ΕΟΦ: Παρακολούθηση επάρκειας αγοράς","url":"https://www.eof.gr/eparkeia-agoras/","confirms":"Αναρτημένη «Λίστα φαρμακευτικών σκευασμάτων περιορισμένης διαθεσιμότητας» με ημερομηνία 30.4.2026 και απόφαση ΕΟΦ 22674/19.02.2026 για προσωρινή απαγόρευση παράλληλων εξαγωγών."}]'::jsonb, '2026-09-14'::date, true, now()),
  ('prostimo-emvoliasmou-elegxos-myaade', 340, 'health', 'Έλεγξε στο myAADE αν διαγράφηκε πρόστιμο μη εμβολιασμού', array['συνταξιούχος']::text[], 'Αν είχες πρόστιμο επειδή δεν εμβολιάστηκες κατά της COVID-19 (αφορούσε όσους γεννήθηκαν έως 31.12.1961), ελέγχεις αν διαγράφηκε μαζί με τους τόκους, ώστε να μην πληρώσεις κάτι που δεν οφείλεις.', 'Ν. 5102/2024, άρθρο 49 (τροποποίηση άρθρου 24 Ν. 4865/2021)', '/tekmiria/epitirisi', '["Μπες στο myAADE με τους κωδικούς σου και δες τις οφειλές σου.","Έλεγξε αν εμφανίζεται ακόμη πρόστιμο για μη εμβολιασμό κατά της COVID-19 ή τόκοι για αυτό. Ο Ν. 5102/2024 (άρθρο 49) διαγράφει τα πρόστιμα που δεν είχαν εισπραχθεί έως 13.4.2024, μαζί με τους τόκους εκπρόθεσμης καταβολής.","Αν το πρόστιμο φαίνεται ακόμη, ρώτα την ΑΑΔΕ μέσω my1521 (τηλέφωνο 1521 ή ψηφιακά) και ανέφερε την εγκύκλιο Ο.3019/23.4.2024."]'::jsonb, 'Η διαγραφή αφορά μόνο πρόστιμα που δεν είχαν εισπραχθεί έως 13.4.2024. Ο νόμος δεν προβλέπει επιστροφή σε όσους είχαν ήδη πληρώσει. Αν είχες πληρώσει μέρος του προστίμου, είχες ρύθμιση σε δόσεις ή εκκρεμεί υπόθεση στο δικαστήριο, ρώτα την ΑΑΔΕ ή δικηγόρο τι ισχύει για σένα.', null, null, 'https://myaade.gov.gr/', '[{"title":"ΑΑΔΕ: Ο. 3019/23-04-2024","url":"https://www.aade.gr/egkyklioi-kai-apofaseis/o-3019-23-04-2024","confirms":"Η εγκύκλιος Ο.3019 της 23.4.2024 κοινοποιεί το άρθρο 49 Ν. 5102/2024 για διαγραφή μη εισπραχθέντων προστίμων ανεμβολίαστων."},{"title":"ΑΑΔΕ: Ο.3019/2024 (PDF) – Κοινοποίηση των διατάξεων των άρθρων 12, 49, 74 και 75 του ν. 5102/2024","url":"https://www.aade.gr/sites/default/files/2024-04/O.3019_2024.pdf","confirms":"Κείμενο της νέας παρ. Δ του άρθρου 24 Ν. 4865/2021: «Διαγράφονται τα διοικητικά πρόστιμα της παρ. 4 [...] μετά των αναλογούντων τόκων εκπρόθεσμης καταβολής, εφόσον δεν έχουν εισπραχθεί έως την έναρξη ισχύος της παρούσας»· έναρξη ισχύος 13.4.2024 (ΦΕΚ Α'' 55)."},{"title":"myAADE (σελίδα σύνδεσης)","url":"https://www1.aade.gr/gsisapps5/myaade/#!/arxiki","confirms":"Η επίσημη πύλη myAADE φορτώνει (σελίδα σύνδεσης)."},{"title":"myaade.gov.gr (ανακατεύθυνση)","url":"https://myaade.gov.gr/","confirms":"Η σύντομη επίσημη διεύθυνση ανακατευθύνει στην πύλη myAADE (www1.aade.gr/gsisapps5/myaade)."},{"title":"ΑΑΔΕ: myAADEapp","url":"https://www.aade.gr/en/myaadeapp","confirms":"Μέσω myAADE ο πολίτης βλέπει τον φορολογικό του λογαριασμό και κάνει πληρωμές."},{"title":"ΑΑΔΕ: my1521 – Παρουσίαση του νέου Κέντρου Εξυπηρέτησης Φορολογουμένων (2.9.2025)","url":"https://www.aade.gr/anakoinoseis/ekdiloseis/ekdiloseis/my1521-paroysiasi-toy-neoy-kentroy-exypiretisis-forologoymenon-tis-aade-292025","confirms":"Το my1521 είναι το κεντρικό σημείο επικοινωνίας της ΑΑΔΕ, με τηλέφωνο 1521 και ψηφιακό κανάλι για ερωτήματα και παρακολούθηση."},{"title":"my1521 – ΑΑΔΕ","url":"https://1521.aade.gr/","confirms":"Η σελίδα του my1521 φορτώνει."},{"title":"emvolio.gov.gr: Απαιτούμενες ενέργειες πολιτών σε σχέση με τα πρόστιμα της παρ. 4 του άρθρου 24 του ν. 4865/2021","url":"https://emvolio.gov.gr/prostima","confirms":"Τα πρόστιμα επιβλήθηκαν βάσει της παρ. 4 του άρθρου 24 Ν. 4865/2021 και αιτήματα πολιτών διαχειρίζονταν μέσω myAADE (σελίδα του 2022, πριν τη διαγραφή)."},{"title":"Ν. 4865/2021, άρθρο 24 (e-nomothesia.gr)","url":"https://www.e-nomothesia.gr/kat-ygeia/nomos-4865-2021-phek-238a-4-12-2021.html","confirms":"Η υποχρέωση εμβολιασμού και το πρόστιμο αφορούσαν όσους είχαν γεννηθεί έως 31.12.1961."}]'::jsonb, '2026-09-14'::date, true, now()),
  ('kamera-kok-thyrida-enstasi', 350, 'health', 'Πρόστιμο από κάμερα: έλεγξε θυρίδα και προθεσμία ένστασης', array['οδηγός']::text[], 'Μαθαίνεις πού έρχεται το πρόστιμο από κάμερα και πώς κάνεις ένσταση ή δηλώνεις τον πραγματικό οδηγό μέσα στις σύντομες προθεσμίες.', 'ΚΟΚ (ν. 5209/2025) άρθρο 107, όπως άλλαξε με τον ν. 5256/2025· ΚΥΑ 68/2026 και ΚΥΑ 7011/7/59-ιδ΄/2023', '/tekmiria/epitirisi', '["Γράψου στο Εθνικό Μητρώο Επικοινωνίας (ΕΜΕπ) στο gov.gr και έλεγξε ότι το κινητό και το email σου είναι σωστά. Τα πρόστιμα από τις κάμερες στέλνονται ηλεκτρονικά στη Θυρίδα Πολίτη στο gov.gr και στο Gov.gr Wallet. Χωρίς εγγραφή στο ΕΜΕπ δεν μπορείς να κάνεις ηλεκτρονική ένσταση.","Μόλις λάβεις ειδοποίηση, άνοιξε τη θυρίδα σου στο gov.gr και διάβασε την πράξη βεβαίωσης παράβασης.","Αν οδηγούσε άλλος, ως ιδιοκτήτης κάνε υπεύθυνη δήλωση μέσα σε 7 ημέρες από την επίδοση. Την καταθέτεις στο αστυνομικό τμήμα της περιοχής σου ή στην υπηρεσία που βεβαίωσε την παράβαση. Γράφεις ότι δεν οδηγούσες εσύ και ποιος οδηγούσε, και φέρνεις και υπεύθυνη δήλωση του οδηγού (ΚΟΚ άρθρο 107 παρ. 6). Δήλωσε άλλον οδηγό μόνο αν είναι αλήθεια: η ψευδής υπεύθυνη δήλωση είναι ποινικό αδίκημα.","Αν διαφωνείς με την παράβαση, κάνε ένσταση μέσα σε 3 ημέρες από την επίδοση (ΚΟΚ άρθρο 107 παρ. 2), στην υπηρεσία του gov.gr «Ένσταση για πράξη βεβαίωσης παράβασης της ΕΛΑΣ». Μπαίνεις με κωδικούς Taxisnet, επιβεβαιώνεις με κωδικό μιας χρήσης στο κινητό ή με το Gov.gr Wallet και ανεβάζεις τα έγγραφα που στηρίζουν την ένστασή σου.","Η απάντηση για την ένσταση, αποδοχή ή αιτιολογημένη απόρριψη, έρχεται στη θυρίδα σου στο gov.gr. Αν απορριφθεί και θέλεις να συνεχίσεις, ρώτα αμέσως δικηγόρο.","Αν δεν πληρώσεις μέσα σε 8 μήνες από την κοινοποίηση της πράξης επιβολής του προστίμου, το πρόστιμο βεβαιώνεται με προσαύξηση 20% και στέλνεται για είσπραξη στην ΑΑΔΕ (ΚΟΚ άρθρο 107 παρ. 5 και 7). Αυτό δεν είναι προθεσμία για ένσταση: η ένσταση έχει πολύ πιο σύντομη προθεσμία."]'::jsonb, 'Οι προθεσμίες είναι πολύ σύντομες και δεν είναι απολύτως ξεκάθαρο από ποια μέρα μετράνε. Για να είσαι ασφαλής, κάνε την ένσταση ή τη δήλωση άλλου οδηγού μέσα σε 3 ημέρες από τη μέρα που η κλήση μπήκε στη θυρίδα σου ή σε ειδοποίησε το Gov.gr Wallet. Αν ως ιδιοκτήτης δεν δηλώσεις άλλον οδηγό μέσα σε 7 ημέρες, ο νόμος θεωρεί εσένα παραβάτη.', 'Κινήσου την ίδια μέρα που θα δεις την κλήση. Ένσταση: 3 ημέρες από την επίδοση (ΚΟΚ άρθρο 107 παρ. 2). Δήλωση άλλου οδηγού: 7 ημέρες από την επίδοση (άρθρο 107 παρ. 6). Επειδή δεν είναι σίγουρο πότε θεωρείται ότι έγινε η επίδοση στη θυρίδα, μέτρα από τη μέρα που μπήκε η κλήση στη θυρίδα σου. Πληρωμή: 8 μήνες από την κοινοποίηση της πράξης επιβολής, αλλιώς προσαύξηση 20%.', 'https://api.et.gr/apiLAW/1/2025/5256/pdf', 'https://www.gov.gr/el/services/1001781/enstase-gia-praxe-bebaioses-parabases', '[{"title":"ΦΕΚ Α΄ 223/08.12.2025 — Ν. 5256/2025 (Εθνικό Τυπογραφείο)","url":"https://api.et.gr/apiLAW/1/2025/5256/pdf","confirms":"Άρθρο 22: αλλάζει το άρθρο 107 ΚΟΚ, μεταξύ άλλων την παρ. 6 (υπεύθυνη δήλωση ιδιοκτήτη σε αποκλειστική προθεσμία 7 ημερών από την επίδοση) και τις παρ. 5 και 7 (πληρωμή σε 8 μήνες, αλλιώς προσαύξηση 20%). Κατά το άρθρο 49 παρ. 2, το νέο ψηφιακό σύστημα των άρθρων 12-13 ισχύει μόνο μετά από διαπιστωτική πράξη."},{"title":"ΚΟΚ (ν. 5209/2025), άρθρο 107 παρ. 2 — κωδικοποιημένο κείμενο (taxheaven.gr)","url":"https://www.taxheaven.gr/law/5209/2025/arthro/107/paragrafos/2","confirms":"Αντιρρήσεις κατά της βεβαίωσης παράβασης εντός προθεσμίας τριών ημερών από την επίδοση."},{"title":"ΚΥΑ 14028 ΕΞ 2026 (ΦΕΚ Β΄ 2400/29.4.2026)","url":"https://www.e-nomothesia.gr/sygkoinonies-metafores/kya-14028-eks-2026.html","confirms":"Στο προοίμιο: δεν είχε εκδοθεί η διαπιστωτική πράξη του άρθρου 23 παρ. 8 του ν. 5256/2025."},{"title":"Υπουργείο Προστασίας του Πολίτη — Ξεκίνησε η βεβαίωση κλήσεων από τις κάμερες (30.3.2026)","url":"https://www.minocp.gov.gr/2026/03/30/30-03-2026-xekinise-i-vevaiosi-kliseon-apo-tis-kameres-technitis-noimosynis-kai-tis-kameres-ton-leoforeion-psifiaka-oi-eidopoiiseis-sti-thyrida-politi-sto-gov-gr-wallet/","confirms":"Οι κλήσεις από τις κάμερες στέλνονται στη Θυρίδα Πολίτη στο gov.gr και στο Gov.gr Wallet."},{"title":"ΚΥΑ 7011/7/59-ιδ΄/2023 (ΦΕΚ Β΄ 6127/2023)","url":"https://www.dsanet.gr/Epikairothta/Nomothesia/6127.PDF","confirms":"Άρθρο 3: ηλεκτρονική ένσταση μέσω gov.gr με αυθεντικοποίηση και κωδικό μιας χρήσης ή Gov.gr Wallet· η απάντηση στέλνεται στη θυρίδα."},{"title":"gov.gr — Ένσταση για πράξη βεβαίωσης παράβασης της ΕΛΑΣ","url":"https://www.gov.gr/el/services/1001781/enstase-gia-praxe-bebaioses-parabases","confirms":"Η ηλεκτρονική υπηρεσία ένστασης: κωδικοί Taxisnet, εγγραφή στο ΕΜΕπ και email."},{"title":"gov.gr — Θυρίδα πολίτη","url":"https://www.gov.gr/ipiresies/polites-kai-kathemerinoteta/stoikheia-polite-kai-tautopoietika-eggrapha/thurida-polite","confirms":"Η επίσημη υπηρεσία Θυρίδα πολίτη στο gov.gr."}]'::jsonb, '2026-09-14'::date, true, now()),
  ('apodimoi-new-registration-national-elections', 410, 'rights', 'Κάνε νέα εγγραφή για να ψηφίσεις από το εξωτερικό', array['Έλληνας εξωτερικού']::text[], 'Αν κάνεις εγκαίρως την αίτηση, μπορείς να ψηφίσεις στις επόμενες βουλευτικές εκλογές χωρίς να ταξιδέψεις στην Ελλάδα, επιστολικά ή σε εκλογικό τμήμα του εξωτερικού.', 'Ν. 4648/2019, όπως τροποποιήθηκε με τον Ν. 5285/2026', '/tekmiria/nomoi', '["Έλεγξε αν σε αφορά: μπορείς να γραφτείς αν είσαι γραμμένος σε εκλογικό κατάλογο δήμου στην Ελλάδα και θα βρίσκεσαι μόνιμα ή προσωρινά εκτός Ελλάδας την ημέρα των εκλογών.","Μπες στην εφαρμογή apodimoi.ypes.gov.gr με τους κωδικούς Taxisnet. Αν δεν έχεις κωδικούς, χρειάζεσαι αριθμό και ημερομηνία έκδοσης του ελληνικού διαβατηρίου, ημερομηνία γέννησης και κινητό τηλέφωνο. Θα κάνεις και ταυτοποίηση από απόσταση με φωτογραφία του προσώπου σου και του διαβατηρίου.","Κάνε νέα αίτηση ακόμη κι αν είχες γραφτεί παλιότερα για εθνικές εκλογές ή ευρωεκλογές. Η παλιά εγγραφή δεν ισχύει πια.","Διάλεξε έναν μόνο τρόπο: αυτοπροσώπως σε πόλη του εξωτερικού, με επιστολική ψήφο, ή με επιστολική ψήφο μόνο αν δεν στηθεί τμήμα στην πόλη που διάλεξες. Τμήμα στήνεται μόνο αν γραφτούν τουλάχιστον 30 εκλογείς. Αν δεν στηθεί και έχεις διαλέξει μόνο αυτοπρόσωπη ψήφο, θα ψηφίσεις στο πλησιέστερο τμήμα που θα στηθεί. Στο εξωτερικό η ψηφοφορία γίνεται λίγες ημέρες πριν από τις εκλογές στην Ελλάδα.","Κράτα τον αριθμό πρωτοκόλλου που θα λάβεις με email και SMS. Αν δεν μπορείς να κάνεις την αίτηση online, μπορείς να την κάνεις στο ελληνικό προξενείο χωρίς χρέωση."]'::jsonb, 'Αν διαλέξεις να ψηφίσεις αυτοπροσώπως στο εξωτερικό, δεν μπορείς να ψηφίσεις στην Ελλάδα την ημέρα των εκλογών, ακόμη κι αν τελικά δεν πας στην κάλπη του εξωτερικού.', 'Κάνε την αίτηση τώρα: οι εκλογές μπορεί να προκηρυχθούν με λίγες ημέρες προειδοποίηση. Για να ψηφίσεις στις επόμενες βουλευτικές εκλογές, η αίτηση πρέπει να έχει γίνει το αργότερο την επόμενη ημέρα από την έκδοση του προεδρικού διατάγματος που τις προκηρύσσει. Αιτήσεις μετά από αυτό ισχύουν μόνο για τις εκλογές που θα ακολουθήσουν.', 'https://www.ypes.gr/cat-faqs/syxn-erot-eklog-eksot/', 'https://apodimoi.ypes.gov.gr/', '[{"title":"Υπουργείο Εσωτερικών - Συχνές Ερωτήσεις εκλογέων εξωτερικού (απαντήσεις με ημερομηνία 14.09.2026 και 05.08.2026)","url":"https://www.ypes.gr/cat-faqs/syxn-erot-eklog-eksot/","confirms":"Καταληκτική προθεσμία έως την επόμενη ημέρα από τη δημοσίευση του ΠΔ προκήρυξης· η προηγούμενη εγγραφή παύει να ισχύει και χρειάζεται νέα αίτηση· όποιος επιλέξει αυτοπρόσωπη παρουσία στο εξωτερικό δεν μπορεί να ψηφίσει στην Ελλάδα· η αίτηση μέσω προξενείου γίνεται χωρίς χρέωση· αποδεικτικό με αριθμό πρωτοκόλλου σε email και κινητό."},{"title":"Υπουργείο Εσωτερικών - Εγκύκλιος 17, αρ. πρωτ. 43447/31.07.2026: Άσκηση εκλογικού δικαιώματος εκλογέων εκτός Επικράτειας στις βουλευτικές εκλογές","url":"https://www.ypes.gr/wp-content/uploads/2026/08/eggr43447-egk17-20260731.pdf","confirms":"Δικαίωμα εγγραφής έχουν όσοι είναι γραμμένοι σε εκλογικό κατάλογο δήμου και βρίσκονται μόνιμα ή προσωρινά εκτός Ελλάδας την ημέρα των εκλογών· ταυτοποίηση με Taxisnet ή με στοιχεία ελληνικού διαβατηρίου· οι τρεις επιλογές τρόπου ψηφοφορίας· η εγγραφή γίνεται οποτεδήποτε· η προξενική συνδρομή παρέχεται ατελώς· προηγούμενες εγγραφές (Ν. 4648/2019 και Ν. 5083/2024) παύουν να ισχύουν."},{"title":"Ν. 5285/2026 (ΦΕΚ 33/Α/5-3-2026) - κείμενο νόμου στο e-nomothesia.gr","url":"https://www.e-nomothesia.gr/kat-bouli-bouleutes/ekloges/nomos-5285-2026.html","confirms":"Άρθρο 16 παρ. 2 (νέα παρ. 3Α άρθρου 2 Ν. 4648/2019): επιλογή ενός από τρεις τρόπους ψηφοφορίας· άρθρο 18 (νέο άρθρο 4 Ν. 4648/2019, παρ. 6): αίτηση, ακύρωση ή τροποποίηση έως την επόμενη ημέρα από την έκδοση του ΠΔ προκήρυξης· άρθρο 25: το Μέρος Β'' ισχύει από τη δημοσίευση υπό την προϋπόθεση πλειοψηφίας 2/3."},{"title":"Εφαρμογή Εγγραφής Εκλογέων εκτός Επικρατείας για Βουλευτικές Εκλογές (Υπουργείο Εσωτερικών)","url":"https://apodimoi.ypes.gov.gr/","confirms":"Η επίσημη εφαρμογή εγγραφής λειτουργεί στη διεύθυνση αυτή, με τίτλο «Εφαρμογή Εγγραφής Εκλογέων εκτός Επικρατείας για Βουλευτικές Εκλογές»."}]'::jsonb, '2026-09-14'::date, true, now()),
  ('postal-vote-national-elections-abroad', 420, 'rights', 'Ψήφισε επιστολικά στις βουλευτικές εκλογές από το εξωτερικό', array['Έλληνας εξωτερικού']::text[], 'Αν θα είσαι εκτός Ελλάδας την ημέρα των εκλογών, ψηφίζεις με φάκελο που σου στέλνεται στη διεύθυνσή σου, χωρίς να πας σε κάλπη.', 'Ν. 5083/2024, όπως εφαρμόζεται στις βουλευτικές εκλογές με τον Ν. 5285/2026 (άρθρα 15, 21 και 22)', '/tekmiria/nomoi', '["Έλεγξε αν σε αφορά: στις βουλευτικές εκλογές ψηφίζεις επιστολικά μόνο αν γραφτείς στον ειδικό εκλογικό κατάλογο εξωτερικού και δηλώσεις διεύθυνση αποστολής εκτός Ελλάδας. Πρέπει να έχεις διαλέξει επιστολική ψήφο ή επιστολική ψήφο μόνο αν δεν στηθεί εκλογικό τμήμα στην πόλη σου.","Στην αίτηση στο apodimoi.ypes.gov.gr διάλεξε «επιστολική ψήφο» και γράψε πλήρη διεύθυνση στο εξωτερικό. Διεύθυνση στην Ελλάδα δεν γίνεται δεκτή.","Αν αλλάξεις διεύθυνση, κινητό ή email, ενημέρωσε αμέσως την αίτησή σου στην εφαρμογή ή μέσω προξενείου. Αλλαγές που γίνονται από τη δεύτερη ημέρα μετά την προκήρυξη των εκλογών ισχύουν μόνο για τις επόμενες εκλογές. Γι'' αυτό δήλωσε διεύθυνση όπου σίγουρα θα είσαι όταν έρθει ο φάκελος.","Όταν λάβεις τον φάκελο, ψήφισε και δώσε τον πίσω στην εταιρεία courier που σου τον έφερε. Η αποστολή είναι δωρεάν για σένα.","Αν δεν στείλεις τον φάκελο ή δεν φτάσει εγκαίρως, το ΥΠΕΣ προβλέπει ειδοποίηση. Τότε μπορείς να ψηφίσεις αυτοπροσώπως στο εκλογικό σου τμήμα στην Ελλάδα, την ημέρα των εκλογών μετά τις 11:00. Μη βασιστείς μόνο στην ειδοποίηση: έλεγξε μόνος σου την πορεία του φακέλου."]'::jsonb, 'Αν θα είσαι στην Ελλάδα την ημέρα των βουλευτικών εκλογών, δεν μπορείς να ψηφίσεις επιστολικά, γιατί μέσα στη χώρα η επιστολική ψήφος ισχύει μόνο σε ευρωεκλογές και δημοψηφίσματα που δεν γίνονται μαζί με βουλευτικές εκλογές.', 'Η αίτηση πρέπει να έχει γίνει το αργότερο την επόμενη ημέρα από την προκήρυξη των εκλογών. Για να μετρήσει η ψήφος, ο φάκελος πρέπει να φτάσει στην Ελλάδα το αργότερο την παραμονή των εκλογών στις 17:00. Γι'' αυτό δώσ'' τον στην εταιρεία courier την ίδια ή την επόμενη μέρα που τον λαμβάνεις.', 'https://www.ypes.gr/cat-faqs/syxn-erot-eklog-eksot/', 'https://apodimoi.ypes.gov.gr/', '[{"title":"Υπουργείο Εσωτερικών - Επιστολική Ψήφος: Γενικά","url":"https://www.ypes.gr/epistoliki-psifos/epistol-psf-genika/","confirms":"Οι διατάξεις του Ν. 5083/2024 για επιστολική ψήφο ισχύουν αποκλειστικά για ευρωεκλογές και εθνικό δημοψήφισμα, και δεν εφαρμόζονται όταν αυτά γίνονται ταυτόχρονα με βουλευτικές εκλογές. Σε αυτές τις ψηφοφορίες μπορούν να ψηφίσουν επιστολικά και εκλογείς μέσα στη χώρα."},{"title":"Ν. 5285/2026 (ΦΕΚ 33/Α/5-3-2026) - κείμενο νόμου στο e-nomothesia.gr","url":"https://www.e-nomothesia.gr/kat-bouli-bouleutes/ekloges/nomos-5285-2026.html","confirms":"Άρθρο 15: η ψηφοφορία των εκλογέων εκτός Επικράτειας γίνεται είτε αυτοπροσώπως είτε με επιστολική ψήφο κατά τον Ν. 5083/2024· άρθρο 21 παρ. 1: επιστολική ψήφος στις βουλευτικές εκλογές για όσους είναι γραμμένοι στους ειδικούς καταλόγους εξωτερικού, επέλεξαν επιστολική ψήφο και δήλωσαν διεύθυνση αποστολής εκτός Ελλάδας· άρθρο 22 παρ. 2: οι φάκελοι αποστέλλονται μόνο σε αυτούς."},{"title":"Υπουργείο Εσωτερικών - Εγκύκλιος 17, αρ. πρωτ. 43447/31.07.2026","url":"https://www.ypes.gr/wp-content/uploads/2026/08/eggr43447-egk17-20260731.pdf","confirms":"Διευθύνσεις αποστολής εκλογικού υλικού εντός Ελλάδας δεν γίνονται αποδεκτές· όσοι επέλεξαν επιστολική ψήφο και δεν έστειλαν φάκελο ή ο φάκελος δεν παρελήφθη εμπροθέσμως μπορούν να ψηφίσουν αυτοπροσώπως στην Ελλάδα· υποχρέωση επικαιροποίησης διεύθυνσης και στοιχείων επικοινωνίας."},{"title":"Υπουργείο Εσωτερικών - Συχνές Ερωτήσεις εκλογέων εξωτερικού","url":"https://www.ypes.gr/cat-faqs/syxn-erot-eklog-eksot/","confirms":"Επιστροφή του φακέλου (συστημένου και express) εντός μίας ημέρας από την παραλαβή και άφιξη στην Ελλάδα έως την παραμονή των εκλογών στις 17:00· δωρεάν αποστολή μέσω του courier που παρέδωσε το υλικό· αυτοπρόσωπη ψήφος στην Ελλάδα μετά τις 11:00 για όσους δεν έφτασε ο φάκελος· άμεση δήλωση αλλαγής τηλεφώνου ή email."},{"title":"Υπουργείο Εσωτερικών - Δελτίο Τύπου 17.02.2026: Κατατέθηκε στη Βουλή το νομοσχέδιο για την επιστολική ψήφο στους εκτός Ελλάδας εκλογείς","url":"https://www.ypes.gr/katatethike-sti-vouli-to-nomoschedio-tou-yp-esoterikon-gia-tin-epistoliki-psifo-stous-ektos-elladas-eklogeis-kai-tin-eklogiki-perifereia-apodimou-ellinismou/","confirms":"Η ρύθμιση αφορά «επιστολική ψήφο για τους εκτός επικρατείας εκλογείς» στις βουλευτικές εκλογές και απαιτεί πλειοψηφία 2/3 κατά το άρθρο 51 παρ. 4 του Συντάγματος."}]'::jsonb, '2026-09-14'::date, true, now()),
  ('synigoros-complaint-public-service', 430, 'rights', 'Κάνε αναφορά στον Συνήγορο του Πολίτη', array['όλοι']::text[], 'Μια ανεξάρτητη αρχή μπορεί να εξετάσει την υπόθεσή σου και να μεσολαβήσει όταν μια δημόσια υπηρεσία, ένας δήμος ή ένας δημόσιος οργανισμός παραβιάζει τα δικαιώματά σου.', 'Ν. 3094/2003 «Συνήγορος του Πολίτη και άλλες διατάξεις»', '/tekmiria/synora', '["Απευθύνσου πρώτα στη δημόσια υπηρεσία που σε αφορά. Ο Συνήγορος ζητά να έχεις έρθει σε επαφή μαζί της και να μην έχει λυθεί το πρόβλημα.","Υπόβαλε την αναφορά ηλεκτρονικά στο synigoros.gr, με πιστοποίηση μέσω του προσωπικού σου email.","Αν δεν θέλεις online, στείλε την αναφορά ταχυδρομικά στη Χαλκοκονδύλη 17, 104 32 Αθήνα, ή πήγαινε στα γραφεία κατόπιν ραντεβού.","Με τον κωδικό παρακολούθησης αναφοράς (ΚΠΑ) που θα λάβεις στο email σου, έλεγξε online σε ποιο στάδιο βρίσκεται η υπόθεσή σου."]'::jsonb, 'Η αναφορά στον Συνήγορο δεν σταματά τις προθεσμίες για διοικητική προσφυγή ή για δικαστήριο, που συχνά είναι λίγων ημερών ή εβδομάδων. Αν θέλεις να προσβάλεις την πράξη, ρώτα δικηγόρο παράλληλα και μην περιμένεις την απάντηση του Συνηγόρου. Ο Συνήγορος δεν εξετάζει υποθέσεις που εκκρεμούν στα δικαστήρια και δεν λύνει ιδιωτικές διαφορές με τράπεζες, εταιρείες τηλεφωνίας, ιδιώτες παρόχους ρεύματος ή αερίου και καταστήματα, εκτός αν καταγγέλλεις διάκριση.', 'Κάνε την αναφορά μέσα σε 6 μήνες από τότε που έμαθες την πράξη ή την παράλειψη της υπηρεσίας. Αναφορά μετά τους 6 μήνες δεν εξετάζεται.', 'https://www.synigoros.gr/el/category/pws-mporoyme-na-boh8hsoyme', 'https://www.synigoros.gr/el/anafora', '[{"title":"Συνήγορος του Πολίτη - Πώς μπορούμε να βοηθήσουμε","url":"https://www.synigoros.gr/el/category/pws-mporoyme-na-boh8hsoyme","confirms":"Δεν είναι αρμόδιος «εάν έχουν περάσει περισσότεροι από 6 μήνες» από τότε που ο πολίτης πληροφορήθηκε την παράνομη πράξη ή παράλειψη· δεν εκπροσωπεί πολίτες στα δικαστήρια· προϋπόθεση: να έχει προηγηθεί επαφή με τη δημόσια υπηρεσία χωρίς επίλυση."},{"title":"Συνήγορος του Πολίτη - Ηλεκτρονική υποβολή και παρακολούθηση αναφοράς","url":"https://www.synigoros.gr/el/anafora","confirms":"Ηλεκτρονική υποβολή με πιστοποίηση μέσω προσωπικού email· κωδικός παρακολούθησης αναφοράς (ΚΠΑ)· εναλλακτικά αυτοπροσώπως κατόπιν ραντεβού ή ταχυδρομικά στη Χαλκοκονδύλη 17, 104 32 Αθήνα· μη αρμοδιότητα για ιδιωτικές διαφορές με τράπεζες, εταιρείες τηλεφωνίας, ιδιώτες παρόχους ενέργειας και καταστήματα, εκτός αν καταγγέλλεται διάκριση."},{"title":"Συνήγορος του Πολίτη - Υποβολή Ηλεκτρονικής Αναφοράς","url":"https://www.synigoros.gr/el/anafora/ipovoli-anaforas","confirms":"Η σελίδα ηλεκτρονικής υποβολής αναφοράς φορτώνει (το περιεχόμενο της φόρμας αποδίδεται με JavaScript)."},{"title":"Ν. 3094/2003 (ΦΕΚ 10/Α/22-1-2003) - αρχικό κείμενο στο e-nomothesia.gr","url":"https://www.e-nomothesia.gr/kat-synegoros-tou-polite/n-3094-2003.html","confirms":"Άρθρο 3 παρ. 1: αρμοδιότητα για Δημόσιο, ΟΤΑ, ΝΠΔΔ και κρατικά ΝΠΙΔ· άρθρο 4 παρ. 4 (αρχικό κείμενο): η αναφορά υποβάλλεται μέσα σε έξι μήνες αφότου ο ενδιαφερόμενος έλαβε πλήρη γνώση των ενεργειών ή παραλείψεων."}]'::jsonb, '2026-09-14'::date, true, now()),
  ('dpa-complaint-personal-data', 440, 'rights', 'Κατάγγειλε παραβίαση των προσωπικών σου δεδομένων στην Αρχή', array['όλοι']::text[], 'Μπορείς να ζητήσεις από την ανεξάρτητη Αρχή Προστασίας Δεδομένων να εξετάσει αν κάποιος επεξεργάζεται παράνομα τα προσωπικά σου δεδομένα ή δεν σέβεται τα δικαιώματά σου.', 'Κανονισμός (ΕΕ) 2016/679 (ΓΚΠΔ) και Ν. 4624/2019', '/tekmiria/epitirisi', '["Αν το πρόβλημα αφορά δικαίωμά σου (π.χ. πρόσβαση, διόρθωση ή διαγραφή δεδομένων), γράψε πρώτα στον υπεύθυνο επεξεργασίας ή στον Υπεύθυνο Προστασίας Δεδομένων (DPO) του. Η Αρχή ζητά να το έχεις κάνει πριν καταγγείλεις παραβίαση δικαιώματος, και να επισυνάψεις την επικοινωνία.","Περίμενε την απάντηση. Ο ΓΚΠΔ δίνει προθεσμία ενός μήνα, που υπό προϋποθέσεις παρατείνεται κατά δύο μήνες. Αν δεν απαντήσει ή η απάντηση δεν σε ικανοποιεί, μπορείς να προχωρήσεις σε καταγγελία.","Χρησιμοποίησε τον Ψηφιακό Βοηθό της Αρχής για να βρεις τη σωστή φόρμα καταγγελίας.","Υπόβαλε την καταγγελία ηλεκτρονικά στη διαδικτυακή πύλη της Αρχής με κωδικούς Taxisnet και συμπλήρωσε όλα τα υποχρεωτικά πεδία.","Μόνο αν για τεκμηριωμένο λόγο δεν μπορείς να συνδεθείς, στείλε το έντυπο στο complaints@dpa.gr ή ταχυδρομικά στη Λ. Κηφισίας 1-3, 115 23 Αθήνα."]'::jsonb, 'Καταγγελίες ανώνυμες, αόριστες ή χωρίς τα απαιτούμενα στοιχεία μπορεί να μπουν στο αρχείο. Η ενημέρωση που δίνει η Αρχή μέσα σε τρεις μήνες αφορά την κατάσταση της καταγγελίας, όχι απαραίτητα την τελική απόφαση. Η Αρχή δεν επιδικάζει αποζημίωση: γι'' αυτήν χρειάζεται δικαστήριο, με δικές του προθεσμίες.', null, null, 'https://www.dpa.gr/el/wizard_kataggelion', '[{"title":"Αρχή Προστασίας Δεδομένων - Καταγγελία στην Αρχή","url":"https://www.dpa.gr/el/polites/katagelia_stin_arxi","confirms":"Για καταγγελία παραβίασης δικαιώματος είναι υποχρεωτικό να έχεις απευθυνθεί πρώτα στον υπεύθυνο επεξεργασίας· προθεσμία ΓΚΠΔ ενός μήνα με παράταση δύο μηνών υπό προϋποθέσεις· δυνατότητα επικοινωνίας με DPO· υποχρεωτικά πεδία στις ηλεκτρονικές φόρμες· κατ'' εξαίρεση υποβολή με email complaints@dpa.gr ή ταχυδρομικά στη Λ. Κηφισίας 1-3· ανώνυμες, αόριστες ή ελλιπείς καταγγελίες μπορούν να τεθούν στο αρχείο· ενημέρωση εντός τριών μηνών για την πρόοδο, που δεν ταυτίζεται με τον χρόνο διεκπεραίωσης."},{"title":"Αρχή Προστασίας Δεδομένων - Ψηφιακός Βοηθός για την υποβολή καταγγελίας","url":"https://www.dpa.gr/el/wizard_kataggelion","confirms":"Η Αρχή παρέχει Ψηφιακό Βοηθό για τη σωστή υποβολή καταγγελίας· οι πληροφορίες του είναι καθοδηγητικές και δεν δεσμεύουν την Αρχή."},{"title":"Αρχή Προστασίας Δεδομένων - Πρόσβαση στις ηλεκτρονικές υπηρεσίες","url":"https://www.dpa.gr/el/syndesi/prosvasi","confirms":"Η πρόσβαση στις ηλεκτρονικές υπηρεσίες της Αρχής γίνεται με διαπιστευτήρια Taxisnet."}]'::jsonb, '2026-09-14'::date, true, now()),
  ('echr-application-four-months', 450, 'rights', 'Κάνε ατομική προσφυγή στο ΕΔΔΑ μέσα σε τέσσερις μήνες', array['όλοι']::text[], 'Μπορείς να ζητήσεις από το Ευρωπαϊκό Δικαστήριο Δικαιωμάτων του Ανθρώπου να κρίνει αν μια δημόσια αρχή παραβίασε δικαίωμά σου από την Ευρωπαϊκή Σύμβαση, όταν τα ελληνικά δικαστήρια δεν το διόρθωσαν.', 'Ευρωπαϊκή Σύμβαση Δικαιωμάτων του Ανθρώπου, άρθρο 35 παρ. 1, και άρθρο 47 του Κανονισμού του Δικαστηρίου', '/tekmiria/synora', '["Έλεγξε τις βασικές προϋποθέσεις: το παράπονο αφορά δικαίωμα της Σύμβασης, στρέφεται κατά του κράτους (για πράξη ή παράλειψη δημόσιας αρχής, και για το αν το κράτος δεν σε προστάτευσε) και σε αφορά προσωπικά και άμεσα.","Βεβαιώσου ότι έχεις φέρει το ίδιο παράπονο στα ελληνικά δικαστήρια, συνήθως μέχρι το ανώτατο, με τα ένδικα μέσα που μπορούσαν πραγματικά να διορθώσουν το πρόβλημα και τηρώντας τις ελληνικές προθεσμίες. Έκτακτα ή αναποτελεσματικά μέσα δεν σταματούν τους τέσσερις μήνες. Για το ποια είναι η τελική απόφαση στη δική σου υπόθεση, ρώτα δικηγόρο, γιατί από αυτή μετράει το τετράμηνο.","Κατέβασε το επίσημο έντυπο από τη σελίδα του Δικαστηρίου και συμπλήρωσε κάθε πεδίο, με όλα τα απαραίτητα έγγραφα. Ελλιπής προσφυγή δεν εξετάζεται.","Στο αρχικό στάδιο μπορείς να γράψεις στα ελληνικά και δεν πληρώνεις δικαστικά τέλη. Δεν είναι υποχρεωτικό να έχεις δικηγόρο για να καταθέσεις, αλλά οι περισσότερες προσφυγές απορρίπτονται για τυπικούς λόγους, οπότε η βοήθεια δικηγόρου αξίζει.","Εκτύπωσε, υπόγραψε και στείλε το έντυπο ταχυδρομικά στο Δικαστήριο στο Στρασβούργο. Αποστολή με φαξ δεν διακόπτει την προθεσμία."]'::jsonb, 'Η προθεσμία διακόπτεται μόνο όταν στείλεις πλήρη προσφυγή, και αν το έντυπο απορριφθεί ως ελλιπές μπορεί να μη μείνει χρόνος για νέο, οπότε μην αφήνεις την αποστολή για τις τελευταίες ημέρες.', 'Μέσα σε τέσσερις μήνες από την τελική εθνική απόφαση. Για να είσαι ασφαλής, μέτρα από την πιο νωρίς ημερομηνία: από την έκδοση της απόφασης ή από τη στιγμή που εσύ ή ο δικηγόρος σου την μάθατε. Αν δεν υπήρχε αποτελεσματικό ένδικο μέσο, μετράει από την ημέρα της πράξης ή του γεγονότος. Η προθεσμία λήγει την τελευταία ημέρα των τεσσάρων μηνών, ακόμη κι αν είναι Κυριακή ή αργία.', 'https://www.echr.coe.int/documents/d/echr/application_notes_eng', 'https://www.echr.coe.int/apply-to-the-court', '[{"title":"ECHR - Apply to the Court","url":"https://www.echr.coe.int/apply-to-the-court","confirms":"Το έντυπο κατεβαίνει, συμπληρώνεται, εκτυπώνεται, υπογράφεται και αποστέλλεται ταχυδρομικά στο Δικαστήριο (The Registrar, 67075 Strasbourg Cedex)· δεν χρησιμοποιείται άλλο έντυπο· ελλιπής προσφυγή δεν εξετάζεται (άρθρο 47)· αποστολή με φαξ δεν διακόπτει την τετράμηνη προθεσμία."},{"title":"ECHR - Notes for filling in the application form (ENG - 2026/1)","url":"https://www.echr.coe.int/documents/d/echr/application_notes_eng","confirms":"Προθεσμία τεσσάρων μηνών από την τελική εθνική απόφαση (από την έκδοση ή επίδοση· από την πράξη όταν δεν υπάρχει αποτελεσματικό ένδικο μέσο)· λήγει την τελευταία ημέρα ακόμη κι αν είναι Κυριακή ή αργία· διακόπτεται μόνο με πλήρη προσφυγή· εξάντληση εθνικών ένδικων μέσων· βασικές προϋποθέσεις παραδεκτού· δυνατότητα γραφής σε επίσημη γλώσσα κράτους μέλους στο αρχικό στάδιο· δεν απαιτείται δικηγόρος κατά την κατάθεση· δεν υπάρχουν δικαστικά τέλη."}]'::jsonb, '2026-09-14'::date, true, now())
on conflict (id) do update set
  sort = excluded.sort, theme = excluded.theme, title = excluded.title, who = excluded.who,
  benefit = excluded.benefit, law = excluded.law, nomosio_ref = excluded.nomosio_ref,
  steps = excluded.steps, watch_out = excluded.watch_out, deadline_text = excluded.deadline_text,
  deadline_url = excluded.deadline_url, action_url = excluded.action_url, sources = excluded.sources,
  checked_on = excluded.checked_on, active = true, updated_at = now();
update public.nomosio_moves set active = false, updated_at = now()
  where active and id not in ('yperories-dikaiomata-arnisi-40', 'myergani-elegxos-oron-yperorion', 'katotatos-misthos-920-elegxos-misthodosias', 'parakratisi-forou-2026-neoi-goneis', 'arogi-aitisi-meta-katastrofi', 'nea-taftotita-prin-to-taxidi', 'prosopikos-arithmos-myinfo', 'taftotita-sto-kinito-gov-gr-wallet', 'adeia-politikou-gamou-gov-gr', 'prolamvano-dorean-proliptikes', 'lista-xeirourgeion-prin-plirosis', 'elleipsi-farmakou-rota-farmakopoio', 'prostimo-emvoliasmou-elegxos-myaade', 'kamera-kok-thyrida-enstasi', 'apodimoi-new-registration-national-elections', 'postal-vote-national-elections-abroad', 'synigoros-complaint-public-service', 'dpa-complaint-personal-data', 'echr-application-four-months');
commit;
